    ["05-d1"] = {name="The Hall of Thanes", entrance="Ironforge 27.63, 47.83", pickup="On your way through Dun Morogh and Loch Modan, pick up the pre-dungeon quests first; there's no need to backtrack just before entering. Skyborne skip 01-Stop 9: on your first visit to Ironforge, head east to Dun Morogh to find Earthseer Farsen, finish Farsen's Watch, Nip 'Em in the Bud and Underground Map, then return to Ironforge. If you'd rather not detour, skip the Old Ironforge Incursion.", pickupS={{"On your way through Dun Morogh and Loch Modan, pick up the pre-dungeon quests first; there's no need to backtrack just before entering"}, {"Skyborne skip 01-Stop 9: on your first visit to Ironforge, head east to Dun Morogh to find Earthseer Farsen, finish Farsen's Watch, Nip 'Em in the Bud and Underground Map, then return to Ironforge", {race={"天裔"}}}, {"If you'd rather not detour, skip the Old Ironforge Incursion"}}, steps={[1]={npc="Dark Iron Map", npcObj=true, tag="Dungeon prereq"}, [2]={npc="Earthseer Farsen", tgt="Earthseer Farsen", tag="Dungeon prereq"}, [3]={npc="Earthseer Farsen", tgt="Earthseer Farsen"}, [4]={npc="Afadra Dunwall", tgt="Afadra Dunwall"}, [5]={npc="Thom Filch", tgt="Thom Filch"}, [6]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [7]={text="The Hall of Thanes entrance"}, [8]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [9]={hint="Kill 15 Enraged Apparitions, 10 Tormented Souls and put the spirit of Anvilmar to rest."}, [10]={hint="Collect 8 Dwarven Heirlooms from the Hall of Thanes."}, [11]={hint="Enter the Hall of Thanes beneath Old Ironforge and claim the Head of Durgen Dirgehammer."}, [12]={npc="Treaty of Understanding", npcObj=true, desc="The last boss fears at about 35% health. Clear the adds first, then pull the boss back into the previous room. There's a lever next to the quest giver. Pull it to open the door and run straight out."}, [13]={npc="Thom Filch", tgt="Thom Filch"}, [14]={npc="Afadra Dunwall", tgt="Afadra Dunwall"}, [15]={npc="