"}, [57]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [58]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [59]={hint="Use the Empty Cliffspring Falls Sampler to draw a sample of water from the mouth of the cave by the falls.", desc="Take the druid-only flight from Nighthaven to Rut'theran Village, then fly to Auberdine."}, [60]={npc="Alanndarian Nightsong", tgt="Alanndarian Nightsong"}, [61]={npc="Alanndarian Nightsong", tgt="Alanndarian Nightsong", desc="Gather Earthroot and Lunar Fungus in Darkshore, then turn them in at Auberdine."}, [62]={hint="Bring 5 Earthroot and 12 Lunar Funguses to Alanndarian Nightsong in Auberdine so she may make a curative salve.", desc="Gather Earthroot and Lunar Fungus in Darkshore, then turn them in at Auberdine."}, [63]={npc="Alanndarian Nightsong", tgt="Alanndarian Nightsong", desc="Gather Earthroot and Lunar Fungus in Darkshore, then turn them in at Auberdine."}, [64]={npc="Alanndarian Nightsong", tgt="Alanndarian Nightsong", desc="Use the cure on the sick deer in Darkshore."}, [65]={hint="Use the Curative Animal Salve on 10 Sickly Deer that are located throughout Darkshore; doing so should cure them. Sickly Deer have been reported starting south of the Cliffspring River to the north of Auberdine and extending all the way into southern Darkshore where the edge of Ashenvale begins.", desc="Use the cure on the sick deer in Darkshore."}, [66]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="After curing 10 deer, use Teleport: Moonglade to go back and turn in."}, [67]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="Turn in to learn Cure Poison."}, [68]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker", desc="Turn in the quest to learn Cure Poison. Take the druid-only flight from Nighthaven to Rut'theran Village, then use the portal in the village to enter Darnassus."}, [69]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker"}, [70]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [71]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="Find the Shrine Bauble at the bottom of Lake Elune'ara."}, [72]={hint="Find a Shrine Bauble in Lake Elune'ara, and take it to the Shrine of Remulos in northwestern Moonglade. Once there, use the Shrine Bauble.", desc="Find the Shrine Bauble at the bottom of Lake Elune'ara."}, [73]={npc="Tajarri", tgt="Tajarri", desc="Find the Shrine Bauble at the bottom of Lake Elune'ara."}, [74]={npc="Tajarri", tgt="Tajarri", desc="The two strange locked chests each hold half of a pendant: one is on the sea floor north of Auberdine in Darkshore, the other is on the sea floor off the northwest coast of Westfall."}, [75]={hint="Find the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance. Speak with the residents of Moonglade to learn clues as to where these items may be located.", desc="Take the druid-only flight from Nighthaven to Rut'theran Village, fly to Auberdine, and swim north to the locked chest on the sea floor. Then take the boat from Auberdine to Stormwind, fly to Sentinel Hill, and head northwest to the coast and dive in to open the other locked chest."}, [76]={text="Once you have both halves, use Teleport: Moonglade to go back and combine the pendant halves near the Shrine of Remulos."}, [77]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [78]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="Turn in to learn Aquatic Form."}, [79]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker", desc="Turn in the quest to learn Aquatic Form. Take the druid-only flight from Nighthaven to Rut'theran Village, then use the portal in the village to enter Darnassus."}}},
    ["02-13"] = {steps={[1]={npc="Gubber Blump", tgt="Gubber Blump"}, [2]={npc="WANTED: Murkdeep!", npcObj=true}, [3]={npc="Archaeologist Hollee", tgt="Archaeologist Hollee"}, [4]={npc="Archaeologist Hollee", tgt="Archaeologist Hollee"}, [5]={npc="Thundris Windweaver", tgt="Thundris Windweaver"}, [6]={npc="Gorbold Steelhand", tgt="Gorbold Steelhand"}, [7]={npc="Gorbold Steelhand", tgt="Gorbold Steelhand"}, [8]={npc="Gershala Nightwhisper", tgt="Gershala Nightwhisper"}, [9]={npc="Terenthis", tgt="Terenthis"}, [10]={npc="Terenthis", tgt="Terenthis"}, [11]={npc="Mysterious Red Crystal", npcObj=true}, [12]={npc="Mysterious Red Crystal", npcObj=true}, [13]={npc="Asterion", tgt="Asterion"}, [14]={npc="Beached Sea Creature", npcObj=true}, [15]={hint="Recover the Silver Dawning's Lockbox and the Mist Veil's Lockbox for Gorbold Steelhand in Auberdine. Both items should be found aboard the wreckage of the ships to the north of the village."}, [16]={npc="Buzzbox 411", npcObj=true}, [17]={npc="Buzzbox 411", npcObj=true}, [18]={npc="Beached Sea Turtle", npcObj=true}, [19]={text="Follow the road to this spot.", desc="From here on, kill any Moonstalker Runts and Rabid Thistle Bears you see."}, [20]={text="Follow the road to this spot."}, [21]={hint="Travel north of Auberdine to the first waterfall along the Cliffspring River and draw a sample from the pool there."}, [22]={hint="Collect 6 Fine Crab Chunks for Gubber Blump in Auberdine."}, [23]={npc="Beached Sea Turtle", npcObj=true}, [24]={npc="Balthule Shadowstrike", tgt="Balthule Shadowstrike"}, [25]={npc="Balthule Shadowstrike", tgt="Balthule Shadowstrike"}, [26]={hint="Collect 4 Worn Parchments for Balthule Shadowstrike near the Tower of Althalaxx."}, [27]={npc="Balthule Shadowstrike", tgt="Balthule Shadowstrike"}, [28]={npc="Balthule Shadowstrike", tgt="Balthule Shadowstrike"}, [29]={hint="Cleanse the forest of 20 Rabid Thistle Bears and return to Tharnariun Treetender in Darkshore."}, [30]={hint="Collect 6 Moonstalker Fangs and place them in Buzzbox 323."}, [31]={hint="Bring 5 Scaber Stalks and 1 Death Cap to Barithras Moonshade in Auberdine."}, [32]={npc="Buzzbox 323", npcObj=true}, [33]={npc="Buzzbox 323", npcObj=true}, [34]={npc="Tharnariun Treetender", tgt="Tharnariun Treetender"}, [35]={npc="Tharnariun Treetender", tgt="Tharnariun Treetender"}, [36]={npc="Gorbold Steelhand", tgt="Gorbold Steelhand"}, [37]={npc="Thundris Windweaver", tgt="Thundris Windweaver"}, [38]={npc="Thundris Windweaver", tgt="Thundris Windweaver"}, [39]={npc="Sentinel Glynda Nal'Shea", tgt="Sentinel Glynda Nal'Shea"}, [40]={npc="Barithras Moonshade", tgt="Barithras Moonshade", desc="Fill the Empty Cleansing Bowl at the moonwell."}, [41]={npc="Barithras Moonshade", tgt="Barithras Moonshade"}, [42]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [43]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [44]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [45]={npc="Gubber Blump", tgt="Gubber Blump"}, [46]={npc="Beached Sea Creature", npcObj=true}, [47]={npc="Beached Sea Creature", npcObj=true, desc="The event only triggers near the campfire. Do it now or when the route passes by again later."}, [48]={npc="Beached Sea Turtle", npcObj=true}, [49]={npc="Beached Sea Turtle", npcObj=true}, [50]={npc="Beached Sea Creature", npcObj=true}, [51]={text="Follow the road to this spot."}, [52]={npc="Sentinel Aynasha", tgt="Sentinel Aynasha", desc="On the way to the next quest, kill any Moonstalker Sire you see (the runts and matriarch will come with it)."}, [53]={hint="Protect Sentinel Aynasha, then speak with Onaeya at Maestra's Post in Ashenvale."}, [54]={npc="Onu", tgt="Onu"}, [55]={npc="Onu", tgt="Onu"}, [56]={npc="Scrying Bowl", npcObj=true, desc="Go to 39.2, 86.9 and use the vial Onu gave you to place it on the ground."}, [57]={npc="Scrying Bowl", npcObj=true}, [58]={npc="Twilight Tome", npcObj=true}, [59]={npc="Twilight Tome", npcObj=true}, [60]={npc="Twilight Tome", npcObj=true}, [61]={hint="Obtain a Peerless Eye from a Twilight Disciple or Thug at the Master's Glaive in Darkshore and find someone in Auberdine who is willing to take it."}, [62]={npc="Therylune", tgt="Therylune", desc="Escort quest: in a group, wait until everyone is at the same step before accepting, and turn off auto-accept."}, [63]={hint="Help Therylune escape, then tell Therysil at the Shrine of Aessina that her sister is safe."}, [64]={npc="Book: The Powers Below", npcObj=true, tag="Optional", desc="Right-click Book: The Powers Below in your bags to start the quest. Mobs in the pit have a low chance to drop Book: The Powers Below. Only accept it if it drops."}, [65]={npc="Prospector Remtravel", tgt="Prospector Remtravel", desc="Escort quest: in a group, wait until everyone is at the same step before accepting, and turn off auto-accept. Let Prospector Remtravel run ahead, and only fight mobs that attack him first."}, [66]={npc="Prospector Remtravel", tgt="Prospector Remtravel"}, [67]={hint="Protect Prospector Remtravel as he searches for the mysterious fossil, then return to Archaeologist Hollee in Auberdine."}, [68]={npc="Buzzbox 525", npcObj=true}, [69]={hint="Find 5 Fine Moonstalker Pelts and return them to Terenthis in Auberdine."}, [70]={npc="Onu", tgt="Onu"}, [71]={npc="Arbal", tgt="Arbal"}, [72]={npc="Onu", tgt="Onu"}, [73]={hint="Find and slay the murloc known as Murkdeep. The creature is thought to be defending the murloc huts south of Auberdine along the water.", desc="Several waves of murlocs come, 2-3 per wave. Pull the last murloc of each wave away from the campfire before killing it, eat and drink, then pull the next wave. Or find a group."}, [74]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [75]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [76]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [77]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [78]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [79]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [80]={npc="Sentinel Glynda Nal'Shea", tgt="Sentinel Glynda Nal'Shea"}, [81]={npc="Archaeologist Hollee", tgt="Archaeologist Hollee"}, [82]={npc="Archaeologist Hollee", tgt="Archaeologist Hollee"}, [83]={npc="Thundris Windweaver", tgt="Thundris Windweaver"}, [84]={npc="Terenthis", tgt="Terenthis"}, [85]={npc="Terenthis", tgt="Terenthis"}, [87]={desc="If Rut'theran Village isn't on your flight map, take the boat like the other races."}, [88]={npc="Nessa Shadowsong", tgt="Nessa Shadowsong"}, [89]={text="Step into the portal in Rut'theran Village to Darnassus."}, [90]={npc="Chief Archaeologist Greywhisker", tgt="Chief Archaeologist Greywhisker"}, [91]={npc="Chief Archaeologist Greywhisker", tgt="Chief Archaeologist Greywhisker"}, [92]={text="Step into the portal in Darnassus back to Rut'theran Village."}, [93]={node="Rut'theran Village"}, [95]={hint="Find and kill the Den Mother."}, [96]={hint="Fill the Empty Cleansing Bowl at the Auberdine Moonwell."}, [97]={hint="Bring 6 Mathystra Relics to Onu at the Grove of the Ancients."}, [98]={hint="Eliminate 12 Stormscale Myrmidons, 8 Stormscale Sorceresses, and 6 Stormscale Warriors for Arbal at the Grove of the Ancients."}, [99]={hint="Find a Stormscale Beastmistress, slay her, and bring back her Rod of Deep Dominion."}, [100]={npc="Renzik The Shiv", tgt="Renzik The Shiv"}, [101]={text="If Lakeshire is selectable, just fly; if not, leave Stormwind along Elwynn Road east into Redridge, and learn the gryphon point on the way into Lakeshire."}, [102]={npc="Lucius", tgt="Lucius"}, [103]={npc="Lucius", tgt="Lucius", desc="Use Pick Lock on the chest near Alther's Mill."}, [104]={hint="Open Lucius's Lockbox, recover the Token of Thievery and return it to Lucius in Lakeshire.", desc="Use Pick Lock on the chest near Alther's Mill."}, [105]={npc="Lucius", tgt="Lucius", desc="Use Pick Lock on the chest near Alther's Mill."}, [106]={npc="Arantir", tgt="Arantir", tag="Optional"}, [107]={hint="Return the Horns of Nez'ra to Arantir's Shadow in Lakeshire.", tag="Optional"}, [108]={npc="Arantir", tgt="Arantir", tag="Optional"}, [109]={npc="Master Mathias Shaw", tgt="Master Mathias Shaw"}, [110]={npc="Agent Kearnen", tgt="Agent Kearnen"}, [111]={npc="Agent Kearnen", tgt="Agent Kearnen", desc="Steal the sealed letter from Klaven's Tower in Westfall. Afterwards, learn Poisons."}, [112]={hint="Steal the Defias Tower Key, break into the Defias Tower and uncover the contents of the Duskwood Chest. Take whatever information you find back to Mathias Shaw in Stormwind. Read Kearnen's Journal to gain insight about the tower.", desc="Steal the sealed letter from Klaven's Tower in Westfall. Afterwards, learn Poisons."}, [113]={npc="Master Mathias Shaw", tgt="Master Mathias Shaw", desc="Steal the sealed letter from Klaven's Tower in Westfall. Afterwards, learn Poisons."}, [114]={npc="Master Mathias Shaw", tgt="Master Mathias Shaw", tag="Optional"}, [115]={npc="Doc Mixilpixil", tgt="Doc Mixilpixil", tag="Optional"}, [116]={npc="Doc Mixilpixil", tgt="Doc Mixilpixil", tag="Optional"}, [117]={npc="Doc Mixilpixil", tgt="Doc Mixilpixil", tag="Optional"}, [118]={npc="Doc Mixilpixil", tgt="Doc Mixilpixil", tag="Optional"}, [119]={hint="Bring Doc Mixilpixil one bundle of Simple Wildflowers, one Leaded Vial, one Bronze Tube, and one Spool of Light Chartreuse Silk Thread. The 'itis' doesn't cure itself, young <fella/lady>.", tag="Optional"}, [120]={npc="Doc Mixilpixil", tgt="Doc Mixilpixil", tag="Optional"}, [121]={npc="High Priestess Laurena", tgt="High Priestess Laurena", desc="Learn Feedback."}, [122]={npc="High Priestess Laurena", tgt="High Priestess Laurena", desc="Learn Feedback."}, [123]={npc="High Priestess Laurena", tgt="High Priestess Laurena", desc="Accept it in Stormwind, turn it in at Ironforge and learn Fear Ward."}, [124]={npc="High Priest Rohan", tgt="High Priest Rohan", desc="Accept it in Stormwind, turn it in at Ironforge and learn Fear Ward."}, [125]={npc="High Priestess Laurena", tgt="High Priestess Laurena", desc="Accept it in Stormwind and turn it in at Dun Morogh."}, [126]={npc="High Priestess Mims", tgt="High Priestess Mims", desc="Accept it in Stormwind and turn it in at Dun Morogh."}, [127]={npc="Jennea Cannon", tgt="Jennea Cannon", desc="The Blue Recluse tavern is in the Mage Quarter of Stormwind."}, [128]={hint="Obtain a Cantation of Manifestation and a Chest of Containment coffers from behind Jennea Cannon. Bring 3 Filled Containment Coffers to Jennea at the Wizard's Sanctum.", desc="The Blue Recluse tavern is in the Mage Quarter of Stormwind."}, [129]={npc="Jennea Cannon", tgt="Jennea Cannon", desc="The Blue Recluse tavern is in the Mage Quarter of Stormwind."}, [130]={npc="Jennea Cannon", tgt="Jennea Cannon", desc="Turn in 10 Linen Cloth and 6 Charged Rift Gems. You can buy the gems at the Auction House."}, [131]={npc="Wynne Larson", tgt="Wynne Larson", desc="Turn in 10 Linen Cloth and 6 Charged Rift Gems. You can buy the gems at the Auction House."}, [132]={npc="Wynne Larson", tgt="Wynne Larson", desc="Rewards Manaweave Robe."}, [133]={npc="Wynne Larson", tgt="Wynne Larson", desc="Rewards Manaweave Robe."}, [134]={npc="Gakin the Darkbinder", tgt="Gakin the Darkbinder"}, [135]={npc="Takar the Seer", tgt="Takar the Seer", desc="Take the boat from Stormwind harbor to Auberdine, follow the Darkshore coast south into Ashenvale, then enter the Barrens from the east through Mor'shan Rampart and head south to find Takar. The Crossroads and Camp Taurajo are Horde strongholds; go around them."}, [136]={npc="Takar the Seer", tgt="Takar the Seer"}, [137]={npc="Takar the Seer", tgt="Takar the Seer"}, [138]={hint="Retrieve the Heartswood from Ashenvale and bring it to Gakin the Darkbinder in the Mage Quarter of Stormwind.", desc="Clear the monsters by the tree first, then click that Cenarion tree to get the heartswood."}, [139]={hint="Retrieve the Wooden Figurine and bring it to Gakin the Darkbinder in the Mage Quarter of Stormwind."}, [140]={npc="Gakin the Darkbinder", tgt="Gakin the Darkbinder", desc="After finishing Ashenvale, hearth back to Stormwind. If your Hearthstone is on cooldown, head north back to Auberdine and take the boat to Stormwind."}, [141]={npc="Gakin the Darkbinder", tgt="Gakin the Darkbinder"}, [142]={npc="Gakin the Darkbinder", tgt="Gakin the Darkbinder", desc="Use it at the summoning circle next to Gakin the Darkbinder and defeat the summoned succubus."}, [143]={hint="Using the Heartswood Core, summon and subdue a succubus, then return the Heartswood Core to Gakin the Darkbinder in the Slaughtered Lamb.", desc="Use it at the summoning circle next to Gakin the Darkbinder and defeat the summoned succubus."}, [144]={npc="Gakin the Darkbinder", tgt="Gakin the Darkbinder", desc="Use it at the summoning circle next to Gakin the Darkbinder and defeat the summoned succubus."}, [145]={npc="Gakin the Darkbinder", tgt="Gakin the Darkbinder"}, [146]={hint="Using the Wooden Figurine, summon and subdue an incubus, then return the Wooden Figurine to Gakin the Darkbinder in the Slaughtered Lamb."}, [147]={npc="Gakin the Darkbinder", tgt="Gakin the Darkbinder"}, [148]={bind="Stormwind"}}},
    ["05-d2"] = {name="Ruins of Lordaeron", entrance="Undercity 72.41, 11.37", steps={[1]={text="Optional, far-off quest: the entrance is in the Ruins of Lordaeron above Undercity, which means crossing Horde territory. Take the Auberdine boat to Menethil Harbor, get off at Southshore and unlock its flight point, then go north through Hillsbrad Foothills and Silverpine Forest to Tirisfal Glades. After the dungeon, hearth back to Stormwind and rejoin 02-Stop 14.", tag="Optional, Unverified"}, [2]={}, [3]={npc="Bloodied Insignia", npcObj=true, desc="Right-click Bloodied Insignia in your bags to start the quest."}, [4]={text="Ruins of Lordaeron entrance"}, [5]={hint="Collect 10 Bloodied Insignias and take them to General Marcus Jonathan in Stormwind City."}, [6]={npc="Crest of Lordaeron", npcObj=true, desc="Right-click Crest of Lordaeron in your bags to start the quest."}, [7]={npc="Blood-Stained Parchment", npcObj=true}, [8]={}, [9]={npc="Orphan Matron Nightingale", tgt="Orphan Matron Nightingale"}, [10]={npc="Lady Dena Kennedy", tgt="Lady Dena Kennedy"}, [11]={npc="General Marcus Jonathan", tgt="General Marcus Jonathan"}}},
    ["02-14"] = {steps={[1]={text="From Stormwind, follow the Elwynn Forest road east into Redridge Mountains and stay on the road to Lakeshire.", tag="Flight path locked. Travel there on foot the first time."}, [2]={npc="Theocritus", tgt="Theocritus"}, [3]={npc="Guard Parker", tgt="Guard Parker"}, [4]={}, [5]={npc="Guard Parker", tgt="Guard Parker", desc="Guard Parker is at the junction on the main road west of Redridge that leads to Elwynn Forest."}, [6]={npc="Darcy", tgt="Darcy"}, [7]={npc="Wiley the Black", tgt="Wiley the Black"}, [8]={npc="Wiley the Black", tgt="Wiley the Black"}, [9]={npc="Dockmaster Baren", tgt="Dockmaster Baren"}, [10]={npc="Dockmaster Baren", tgt="Dockmaster Baren"}, [11]={npc="Magistrate Solomon", tgt="Magistrate Solomon"}, [12]={npc="Verner Osgood", tgt="Verner Osgood"}, [13]={npc="Deputy Feldon", tgt="Deputy Feldon"}, [14]={npc="Deputy Feldon", tgt="Deputy Feldon"}, [15]={npc="Deputy Feldon", tgt="Deputy Feldon"}, [16]={node="Lakeshire"}, [18]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [19]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [21]={npc="General Marcus Jonathan", tgt="General Marcus Jonathan"}, [22]={npc="General Marcus Jonathan", tgt="General Marcus Jonathan"}, [23]={npc="Smith Argus", tgt="Smith Argus"}, [24]={npc="Smith Argus", tgt="Smith Argus"}, [25]={npc="Master Mathias Shaw", tgt="Master Mathias Shaw"}, [26]={npc="Master Mathias Shaw", tgt="Master Mathias Shaw"}, [28]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [29]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [30]={hint="Track down the Defias Messenger in Westfall and bring his message to Stoutmantle."}, [31]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [32]={npc="The Defias Traitor", tgt="The Defias Traitor"}, [33]={hint="Escort the Defias Traitor to the secret hideout of the Defias Brotherhood. Once the Defias Traitor shows you where VanCleef and his men are hiding out, return to Gryan Stoutmantle with the information.", tag="Escort