    ["03-29"] = {steps={[1]={tag="Optional", desc="Little XP in the Darnassus section. Skip if you're in a hurry."}, [2]={text="Step into the portal in Rut'theran Village to Darnassus.", tag="Optional"}, [3]={npc="Thyn'tel Bladeweaver", tgt="Thyn'tel Bladeweaver", tag="Optional"}, [4]={npc="Thyn'tel Bladeweaver", tgt="Thyn'tel Bladeweaver", tag="Optional"}, [5]={hint="Search through Velinde's chest for her journal, then return it along with the key to Thyn'tel Bladeweaver in Darnassus.", tag="Optional"}, [6]={npc="Thyn'tel Bladeweaver", tgt="Thyn'tel Bladeweaver", tag="Optional"}, [7]={npc="Thyn'tel Bladeweaver", tgt="Thyn'tel Bladeweaver", tag="Optional"}, [8]={text="Step into the portal in Darnassus back to Rut'theran Village.", tag="Optional"}, [9]={text="If you did the optional Darnassus quests, fly from Rut'theran Village to Ratchet (changing at Auberdine and Talrendis Point); if you skipped them, fly from Astranaar (changing at Talrendis Point). Follow the main road south, avoid Camp Taurajo, and take the Great Lift down into Thousand Needles. Only use Mor'shan Rampart if neither point is unlocked."}, [10]={text="Follow the road to this spot."}, [11]={node="Thalanaar"}, [12]={npc="Wizzle Brassbolts", tgt="Wizzle Brassbolts"}, [13]={npc="Wizzle Brassbolts", tgt="Wizzle Brassbolts"}, [14]={npc="Fizzle Brassbolts", tgt="Fizzle Brassbolts"}, [15]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [16]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [17]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [18]={npc="Pozzik", tgt="Pozzik"}, [19]={npc="Trackmaster Zherin", tgt="Trackmaster Zherin"}, [20]={hint="Get 10 Hollow Vulture Bones for Pozzik in the Shimmering Flats."}, [21]={hint="Kill 10 Saltstone Basilisks, 10 Saltstone Crystalhides and 6 Saltstone Gazers for Trackmaster Zherin on the Shimmering Flats."}, [22]={hint="Bring 9 Hardened Tortoise Shells to Wizzle Brassbolts in the Shimmering Flats."}, [23]={hint="Bring 30 Rocket Car Parts to Kravel Koalbeard in 