    ["03-30"] = {name="Arathi Highlands", steps={[1]={desc="If Refuge Pointe isn't unlocked, fly to Menethil Harbor, follow the road northeast through the Wetlands, cross Thandol Span into Arathi Highlands and then follow the road to Refuge Pointe."}, [2]={npc="Captain Nials", tgt="Captain Nials"}, [3]={npc="Captain Nials", tgt="Captain Nials", desc="Turn in to Demar Brant at Farholde Keep in the Riverglades; you'll go there at the next stop."}, [4]={npc="Wanted Board", npcObj=true, tag="Optional"}, [5]={npc="Wanted Board", npcObj=true, tag="Optional"}, [6]={npc="Skuerto", tgt="Skuerto"}, [7]={npc="Apprentice Kryten", tgt="Apprentice Kryten"}, [8]={npc="Shards of Myzrael", npcObj=true}, [9]={hint="Gather 12 Motes of Myzrael, then bring them to the Iridescent Shards in Drywhisker Gorge."}, [10]={npc="Iridescent Shards", npcObj=true}, [11]={desc="Grind to about three quarters of level 36."}, [12]={npc="Iridescent Shards", npcObj=true}, [13]={hint="Gather the Burning Key, the Cresting Key and the Thundering Key from the Stone of West Binding, the Stone of East Binding and the Stone of Outer Binding."}, [14]={npc="Quae", tgt="Quae"}, [15]={npc="Quae", tgt="Quae"}, [16]={hint="Find 10 Witherbark Tusks, 4 Witherbark Medicine Pouches and a Shadow Hunter Knife for Apprentice Kryten at Refuge Pointe.", desc="Watch out for the patrolling Forsaken Courier."}, [17]={npc="Apprentice Kryten", tgt="Apprentice Kryten"}, [18]={npc="Skuerto", tgt="Skuerto"}, [19]={hint="Find Trelane's Wand of Invocation and return it to Skuerto at Refuge Pointe."}, [21]={npc="Skuerto", tgt="Skuerto"}, [22]={npc="Skuerto", tgt="Skuerto", tag="Optional"}, [23]={hint="Kill 10 Syndicate Highwaymen and 6 Syndicate Mercenaries."}, [24]={npc="Captain Nials", tgt="Captain Nials"}, [25]={npc="Captain Nials", tgt="Captain Nials", tag="Optional"}, [26]={npc="Stone of Inner Binding", npcObj=true}, [27]={hint="Bring Marez's head to Captain Nials at Refuge Pointe.", tag="Later, on the way"}, [28]={hint="Bring Otto's Head and Falconcrest's Head to Captain Nials at Refuge Pointe.", tag="Later, on the way"}, [29]={hint="Bring 7 Stromgarde Badges to Captain Nials at Refuge Pointe.", tag="Later, on the way"}, [30]={hint="Find an Azure Agate and bring it to Apprentice Kryten at Refuge Pointe.", tag="Later, on the way"}, [31]={npc="Captain Nials", tgt="Captain Nials", tag="Optional"}, [32]={npc="Captain Nials", tgt="Captain Nials", tag="Optional"}, [33]={npc="Captain Nials", tgt="Captain Nials", tag="Optional"}, [34]={npc="Apprentice Kryten", tgt="Apprentice Kryten", tag="Optional"}, [35]={npc="Apprentice Kryten", tgt="Apprentice Kryten", tag="Optional"}, [36]={npc="Skuerto", tgt="Skuerto", tag="Optional"}, [37]={npc="Skuerto", tgt="Skuerto", tag="Optional"}, [38]={npc="Quae", tgt="Quae"}, [39]={npc="Quae", tgt="Quae"}, [40]={npc="Kinelory", tgt="Kinelory"}, [41]={npc="Kinelory", tgt="Kinelory"}, [42]={npc="Quae", tgt="Quae"}, [43]={npc="Quae", tgt="Quae"}, [44]={hint="Find Trelane's Phylactery, Trelane's Orb, and Trelane's Ember Agate, and return them to Skuerto at Refuge Pointe.", tag="Later, on the way"}, [45]={npc="Skuerto", tgt="Skuerto", tag="Optional"}, [46]={npc="Skuerto", tgt="Skuerto", tag="Optional"}, [48]={npc="Phin Odelic", tgt="Phin Odelic"}, [49]={npc="Magistrate Henry Maleb", tgt="Magistrate Henry Maleb"}, [50]={hint="Steal a Syndicate uniform from Northfold Manor to infiltrate Stromgarde Keep.", desc="Steal a Syndicate uniform from Northfold Manor in Arathi Highlands."}, [51]={npc="Syndicate Footlocker", npcObj=true}, [52]={npc="Syndicate Footlocker", npcObj=true}, [53]={hint="While disguised as a member of the Syndicate, find someone inside Stromgarde Keep who knows about the secret deal."}, [54]={npc="Anastasia Miller", tgt="Anastasia Miller"}, [55]={npc="Anastasia Miller", tgt="Anastasia Miller"}, [56]={hint="Find something within Stromgarde Keep to convince Anastasia to give up details of the secret deal."}, [57]={npc="Anastasia Miller", tgt="Anastasia Miller"}