    ["05-d8"] = {name="Scarlet Monastery", entrance="Tirisfal Glades 82.60, 33.80", pickup="Pick up the pre-dungeon quests when you reach Wetlands (2nd visit); no need for a special trip back before the dungeon.", pickupS={{"Pick up the pre-dungeon quests when you reach Wetlands (2nd visit); no need for a special trip back before the dungeon"}}, steps={[1]={npc="Librarian Mae Paledust", tgt="Librarian Mae Paledust"}, [2]={desc="You'll connect through Ironforge."}, [3]={text="From Southshore, go north through Hillsbrad Foothills and the Alterac Mountains, enter Western Plaguelands and head west into Tirisfal Glades, then follow the road to the Scarlet Monastery in the northeast corner.", tag="Unverified"}, [4]={text="Scarlet Monastery entrance"}, [5]={bind="Stormwind"}, [6]={text="Go to the Dwarven District in Stormwind and take the Deeprun Tram to Ironforge."}, [7]={npc="Librarian Mae Paledust", tgt="Librarian Mae Paledust", tag="Optional"}}},
