"}, [65]={npc="Lookout Captain Lolo Longstriker", tgt="Lookout Captain Lolo Longstriker", tag="Group, Optional"}, [66]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands"}, [67]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands", tag="Optional"}, [68]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands"}, [69]={npc="Taskmaster Scrange", tgt="Taskmaster Scrange"}, [70]={npc="Taskmaster Scrange", tgt="Taskmaster Scrange"}, [71]={npc="Master Smith Burninate", tgt="Master Smith Burninate"}, [72]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Optional"}, [73]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [74]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [75]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [76]={npc="Torch of Retribution", npcObj=true}, [77]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [78]={npc="Squire Maltrake", tgt="Squire Maltrake"}, [79]={npc="Squire Maltrake", tgt="Squire Maltrake"}, [80]={hint="Set the North, South, East, and West Sentry Towers on fire by using the Torch of Retribution inside each of the buildings."}, [81]={npc="Altar of Suntara", npcObj=true}, [82]={npc="Dying Archaeologist", tgt="Dying Archaeologist"}, [83]={hint="Slay Lathoric the Black and Obsidion, and return to Thorius in Ironforge with the Head of Lathoric the Black and the Heart of Obsidion."}, [84]={npc="Squire Maltrake", tgt="Squire Maltrake"}, [85]={npc="Hoard of the Black Dragonflight", npcObj=true}, [86]={npc="Hoard of the Black Dragonflight", npcObj=true}, [87]={text="Follow the road to this spot."}, [88]={text="Jump into the lava to die on purpose: one quest can only be accepted as a ghost."}, [89]={text="Run back to your corpse and resurrect."}, [90]={tag="Optional, Group", desc="Level here to 52 only with a Blackrock Depths group. Skip if solo."}, [91]={desc="If your hearthstone is ready, hearth back to Thelsamar and fly from there; otherwise, go back to Thorium Point (37.90, 30.40) and find the flight master."}, [92]={npc="Curator Thoriu