    ["05-d11"] = {name="Blackrock Depths", entrance="Searing Gorge 34.80, 85.30", steps={[1]={desc="The Swamp of Sorrows has no Alliance flight point: head west through Deadwind Pass back to Darkshire and fly from there."}, [2]={text="From Thorium Point, go south through the Searing Gorge and into Blackrock Mountain to the south."}, [3]={npc="Franclorn Forgewright", tgt="Franclorn Forgewright"}, [4]={npc="Franclorn Forgewright", tgt="Franclorn Forgewright"}, [5]={npc="Franclorn Forgewright", tgt="Franclorn Forgewright"}, [6]={text="Blackrock Depths entrance"}, [7]={hint="Slay Fineous Darkvire and recover the great hammer, Ironfel. Take Ironfel to the Shrine of Thaurissan and place it on the statue of Franclorn Forgewright."}, [8]={npc="Monument of Franclorn Forgewright", npcObj=true}, [9]={desc="Leave Blackrock Mountain north through the Searing Gorge, return to Thorium Point and fly from there."}}},
    ["04-46"] = {steps={[1]={desc="The Swamp of Sorrows has no Alliance flight point: head west through Deadwind Pass back to Darkshire and fly from there."}, [2]={npc="Crank Fizzlebub", tgt="Crank Fizzlebub"}, [3]={npc="Crank Fizzlebub", tgt="Crank Fizzlebub"}, [4]={npc="Whiskey Slim", tgt="Whiskey Slim"}, [5]={npc="\"Sea Wolf\" MacKinley", tgt="Sea Wolf MacKinley"}, [6]={npc="Fin Fizracket", tgt="Fin Fizracket", tag="Optional"}, [7]={npc="Oglethorpe Obnoticus", tgt="Oglethorpe Obnoticus"}, [8]={npc="Oglethorpe Obnoticus", tgt="Oglethorpe Obnoticus"}, [9]={npc="Oglethorpe Obnoticus", tgt="Oglethorpe Obnoticus"}, [10]={npc="Oglethorpe Obnoticus", tgt="Oglethorpe Obnoticus"}, [11]={npc="Oglethorpe Obnoticus", tgt="Oglethorpe Obnoticus"}, [12]={tag="Optional"}, [13]={npc="Carefully Folded Note", npcObj=true, desc="Right-click Carefully Folded Note in your bags to start the quest. Right-click the folded note you got earlier to start the quest now."}, [14]={npc="Princess Poobah", tgt="Princess Poobah"}, [15]={npc="Princess Poobah", tgt="Princess Poobah", tag="Optional"}, [16]={hint="Slay King Mukla and return to Princess Poobah with the Key to free her.", tag="Later, on the way"}, [17]={npc="Princess Poobah", tgt="Princess Poobah", tag="Optional"}, [19]={hint="Bring Smotts' Chest to Hecklebury Smotts in Booty Bay.", tag="Later, on the way"}, [20]={hint="Seek out Witch Doctor Unbagwa and have him summon Mokk the Savage. Bring the Heart of Mokk to Fin Fizracket.", tag="Later, on the way"}, [21]={tag="Optional"}, [22]={npc="Fin Fizracket", tgt="Fin Fizracket", tag="Optional"}, [24]={hint="Retrieve the Stone Circle from Marvon Rivetseeker's workshop in Ratchet."}, [26]={npc="Musty Scroll", npcObj=true}, [27]={npc="Musty Scroll", npcObj=true}}},
