    ["04-48"] = {steps={[1]={text="From the mountain road west of Tanaris, take the ramp down into Un'Goro Crater. Torwa Pathfinder is right by the entrance at the bottom of the ramp.", tag="Flight path locked. Travel there on foot the first time."}, [2]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [3]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [4]={npc="A Wrecked Raft", npcObj=true, desc="Collect 7 each of red, blue, green and yellow crystals, and get A Mangled Journal from the raptors."}, [5]={npc="A Small Pack", npcObj=true}, [6]={npc="A Small Pack", npcObj=true}, [7]={hint="Find the carcass of Lar'korwi's freshest kill and steal a Piece of Threshadon Carcass before returning to Torwa Pathfinder in Un'Goro Crater."}, [8]={desc="Kill plants around 67.7, 30.7 until you're halfway through level 49."}, [9]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [10]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [11]={hint="Bring 2 Ravasaur Pheromone Glands to Torwa Pathfinder near the entrance to Un'Goro Crater."}, [12]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [13]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [14]={hint="Using the contents of Torwa's Pouch, summon Lar'korwi and defeat him. Then bring Lar'korwi's Head to Torwa Pathfinder near the entrance to Un'Goro Crater.", tag="Optional", desc="This one is harder. You can save it for when you return to Un'Goro."}, [15]={npc="Karna Remtravel", tgt="Karna Remtravel"}, [16]={npc="Linken", tgt="Linken"}, [17]={npc="Linken", tgt="Linken"}, [18]={node="Marshal's Refuge"}, [19]={npc="Williden Marshal", tgt="Williden Marshal"}, [20]={npc="Hol'anyee Marshal", tgt="Hol'anyee Marshal"}, [21]={npc="Spark Nilminer", tgt="Spark Nilminer"}, [22]={npc="J.D. Collie", tgt="J.D. Collie"}, [23]={npc="J.D. Collie", tgt="J.D. Collie"}, [24]={npc="J.D. Collie", tgt="J.D. Collie"}, [25]={npc="J.D. Collie", tgt="J.D. Collie"}, [26]={npc="J.D. Collie", tgt="J.D. Collie"}, [27]={npc="Beware of Pterrordax", npcObj=true}, [28]={npc="Muigin", tgt="Muigin"}, [29]={npc="Shizzle", tgt="Shizzle"}, [30]={hint="Discover the location of the Northern Crystal Pylon in Un'Goro Crater."}, [31]={hint="Bring 2 Un'Goro Gorilla Pelts, 2 Un'Goro Stomper Pelts, and 2 Un'Goro Thunderer Pelts to Torwa Pathfinder at the entrance of Un'Goro Crater."}, [33]={hint="Bring a Crate of Foodstuffs and Research Equipment to Williden Marshal in Un'Goro Crater."}, [34]={hint="Discover the location of the Eastern Crystal Pylon in Un'Goro Crater."}, [35]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [36]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [37]={text="Follow the road to this spot."}, [38]={text="Follow the road to this spot."}, [39]={hint="Use the Scraping Vial to collect a Hive Wall Sample from one of the Gorishi hive hatcheries in Un'Goro Crater. Look for the chambers with the hanging larval spawns."}, [40]={hint="Discover the location of the Western Crystal Pylon."}, [41]={text="Finish the kill and collection quests you have."}, [42]={hint="Collect 8 Webbed Diemetradon Scales and 8 Webbed Pterrordax Scales for Shizzle in Marshal's Refuge."}, [43]={hint="Collect 15 Bloodpetals and return to Muigin."}, [44]={hint="Kill 10 Pterrordax and 15 Frenzied Pterrordax, then speak to Spraggle Frock at Marshal's Refuge."}, [45]={npc="Shizzle", tgt="Shizzle"}, [46]={npc="Muigin", tgt="Muigin"}, [47]={npc="Muigin", tgt="Muigin"}, [48]={npc="Spraggle Frock", tgt="Spraggle Frock"}, [49]={npc="Spark Nilminer", tgt="Spark Nilminer"}, [50]={npc="Hol'anyee Marshal", tgt="Hol'anyee Marshal"}, [51]={npc="Williden Marshal", tgt="Williden Marshal"}, [52]={npc="A Mangled Journal", npcObj=true, tag="Optional", desc="Right-click to start only if you loot A Mangled Journal from mobs."}, [53]={npc="Williden Marshal", tgt="Williden Marshal", tag="Optional"}, [54]={npc="J.D. Collie", tgt="J.D. Collie"}, [55]={npc="J.D. Collie", tgt="J.D. Collie"}, [56]={npc="J.D. Collie", tgt="J.D. Collie"}, [57]={npc="J.D. Collie", tgt="J.D. Collie"}, [58]={npc="J.D. Collie", tgt="J.D. Collie"}, [60]={bind="Ironforge", desc="If your hearthstone is on cooldown, fly from Marshal's Refuge to Auberdine (via Gadgetzan and Theramore) and skip the next two steps."}, [62]={desc="This boat stops at Southshore on the way. Don't get off until Auberdine."}, [64]={npc="Erelas Ambersky", tgt="Erelas Ambersky"}, [65]={npc="Daryn Lightwind", tgt="Daryn Lightwind"}, [66]={npc="Daryn Lightwind", tgt="Daryn Lightwind"}, [67]={text="Step into the portal in Rut'theran Village to Darnassus."}, [68]={npc="Gracina Spiritmight", tgt="Gracina Spiritmight"}, [69]={npc="Gracina Spiritmight", tgt="Gracina Spiritmight"}, [70]={npc="Astarii Starseeker", tgt="Astarii Starseeker", tag="Optional"}, [71]={text="Step into the portal in Darnassus back to Rut'theran Village."}, [73]={text="Set your hearth in the Astranaar inn (37.00, 49.20).", bind="Astranaar"}, [74]={npc="Maginor Dumas", tgt="Maginor Dumas", tag="Optional", desc="You can skip the Stormwind introduction. You still need to find Sanath Lim-yo first to be teleported up the cliff when you reach Azshara."}, [75]={npc="Sanath Lim-yo", tgt="Sanath Lim-yo", tag="Optional", desc="Turn it in here only if you picked up the introduction."}, [76]={text="Talk to Sanath Lim-yo and ask him to teleport you up the cliff to find Archmage Xylem."}, [77]={npc="Archmage Xylem", tgt="Archmage Xylem"}, [78]={hint="Bring 10 Glittering Dust to Archmage Xylem."}, [79]={npc="Archmage Xylem", tgt="Archmage Xylem", desc="The dust is at the foot of the mountain; go back to Sanath Lim-yo the same way to be teleported up."}, [80]={npc="Archmage Xylem", tgt="Archmage Xylem"}, [81]={hint="Collect 6 Enchanted Coral and return them to Archmage Xylem."}, [82]={npc="Archmage Xylem", tgt="Archmage Xylem"}, [83]={npc="Archmage Xylem", tgt="Archmage Xylem", desc="Morphaz is in the Temple of Atal'Hakkar."}, [84]={hint="Retrieve the Arcane Shard from Morphaz and return to Archmage Xylem.", desc="Morphaz is in the Temple of Atal'Hakkar."}, [85]={npc="Archmage Xylem", tgt="Archmage Xylem", desc="Morphaz is in the Temple of Atal'Hakkar. To get down the cliff, use your Hearthstone or look for the teleport option next to Xylem (needs in-game testing)."}, [86]={npc="Brother Joshua", tgt="Brother Joshua", desc="Accept it in Stormwind and turn it in to Ogtinc in Azshara."}, [87]={npc="Ogtinc", tgt="Ogtinc", desc="Accept it in Stormwind and turn it in to Ogtinc in Azshara."}, [88]={npc="Ogtinc", tgt="Ogtinc"}, [89]={hint="Acquire 4 Healthy Courser Glands and bring them to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath."}, [90]={npc="Ogtinc", tgt="Ogtinc"}, [91]={npc="Ogtinc", tgt="Ogtinc"}, [92]={hint="Acquire an Ichor of Undeath for Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath."}, [93]={npc="Ogtinc", tgt="Ogtinc"}, [94]={npc="Ogtinc", tgt="Ogtinc", desc="Morphaz is in the Temple of Atal'Hakkar."}, [95]={hint="Kill Morphaz in the sunken temple of Atal'Hakkar, and return his blood to Greta Mosshoof in Felwood. The entrance to the sunken temple can be found in the Swamp of Sorrows.", desc="Morphaz is in the Temple of Atal'Hakkar."}, [96]={npc="Greta Mosshoof", tgt="Greta Mosshoof", desc="Morphaz is in the Temple of Atal'Hakkar."}, [97]={npc="Dorion", tgt="Dorion", desc="Accept it in Darnassus (or Ironforge or Stormwind) and turn it in to Ogtinc in Azshara."}, [98]={npc="Ogtinc", tgt="Ogtinc", desc="Accept it in Darnassus (or Ironforge or Stormwind) and turn it in to Ogtinc in Azshara."}, [99]={npc="Ogtinc", tgt="Ogtinc"}, [100]={hint="Bring a pair of Perfect Courser Antlers to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast of the Ruins of Eldarath."}, [101]={npc="Ogtinc", tgt="Ogtinc"}, [102]={npc="Ogtinc", tgt="Ogtinc"}, [103]={hint="Bring 6 Wavethrasher Scales to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath."}, [104]={npc="Ogtinc", tgt="Ogtinc"}, [105]={npc="Ogtinc", tgt="Ogtinc", desc="The green drake is in the Temple of Atal'Hakkar."}, [106]={hint="Bring the Tooth of Morphaz to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.", desc="The green drake is in the Temple of Atal'Hakkar."}, [107]={npc="Ogtinc", tgt="Ogtinc", desc="The green drake is in the Temple of Atal'Hakkar."}}},
    ["04-49"] = {steps={[1]={text="From Astranaar, follow the road north into Felwood.", tag="Flight path locked. Travel there on foot the first time."}, [2]={npc="Arathandris Silversky", tgt="Arathandris Silversky"}, [3]={npc="Grazle", tgt="Grazle"}, [4]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [5]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [6]={npc="Taronn Redfeather", tgt="Taronn Redfeather", tag="Optional"}, [7]={hint="Grazle wants you to prove yourself by killing 6 Deadwood Warriors, 6 Deadwood Pathfinders, and 6 Deadwood Gardeners. Return to him in southern Felwood near the Emerald Sanctuary when you are done."}, [8]={npc="Grazle", tgt="Grazle"}, [9]={npc="Grazle", tgt="Grazle"}, [10]={hint="Kill 11 Jadefire Felsworns, 9 Jadefire Shadowstalkers, 9 Jadefire Rogues, and Xavathras. Return to Eridan Bluewind in Felwood when the task has been completed."}, [11]={hint="Enter Jaedenar and slay 4 Jaedenar Hounds, 4 Jaedenar Guardsmen, 6 Jaedenar Adepts, and 6 Jaedenar Cultists before returning to Greta Mosshoof in Felwood."}, [12]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [13]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [14]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [15]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [16]={hint="Take the Empty Canteen to the Moon Well in the center of Jaedenar and fill it before returning to Greta Mosshoof in Felwood."}, [17]={desc="Kill mobs around 35, 59 in Jaedenar."}, [18]={hint="Seek out and destroy 2 Entropic Beasts and 2 Entropic Horrors while exploring Shatter Scar Vale. After checking to see if the craters there are still filled with corrupt fel water, return to Taronn Redfeather in Felwood.", tag="Optional", desc="This is a dedicated detour with no other objectives nearby. Skip it if you're in a hurry."}, [19]={hint="Eridan Bluewind in Felwood wants you to kill 8 Jadefire Hellcallers, 8 Jadefire Betrayers, 8 Jadefire Tricksters, and Xavaric. Return to Eridan when the task is completed."}, [20]={npc="Flute of Xavaric", npcObj=true, desc="Right-click Flute of Xavaric in your bags to start the quest."}, [21]={hint="Bring the Flute of Xavaric and 5 Jadefire Felbind samples to Eridan Bluewind in southern Felwood."}, [22]={hint="Bring 15 Blood Amber to Arathandris Silversky in Felwood."}, [23]={node="Talonbranch Glade"}, [24]={npc="Nafien", tgt="Nafien"}, [25]={npc="Nafien", tgt="Nafien", tag="Unverified"}, [26]={hint="Nafien would like you to kill 6 Deadwood Den Watchers, 6 Deadwood Avengers, and 6 Deadwood Shamans. Return to him in northern Felwood near the entrance to Timbermaw Hold.", tag="Unverified"}, [27]={npc="Nafien", tgt="Nafien", tag="Unverified"}, [28]={text="Follow the road to this spot.", desc="Enter the Timbermaw Hold cave from here and pass through it to reach Winterspring."}, [29]={node="Moonglade", tag="Unverified", desc="A fork in the Timbermaw Hold cave leads to Moonglade; go over first to unlock the flight path, then return to the cave and head toward Winterspring. For the Mount Hyjal part later you'll fly to Moonglade."}, [30]={npc="Salfa", tgt="Salfa", tag="Unverified"}, [31]={npc="Donova Snowden", tgt="Donova Snowden"}, [32]={npc="Donova Snowden", tgt="Donova Snowden"}, [33]={npc="Meggi Peppinrocker", tgt="Meggi Peppinrocker"}, [34]={npc="Jessica Redpath", tgt="Jessica Redpath"}, [35]={node="Everlook"}, [36]={npc="Niby the Almighty", tgt="Niby the Almighty"}, [37]={npc="Impsy", tgt="Impsy"}, [38]={npc="Impsy", tgt="Impsy"}, [39]={hint="Bring a piece of felcloth to Impsy in Felwood."}, [40]={npc="Impsy", tgt="Impsy"}, [41]={npc="Impsy", tgt="Impsy"}, [42]={hint="Bring 10 Rotting Wood and 4 Bloodvenom Essence to Impsy in Felwood."}, [43]={npc="Impsy", tgt="Impsy"}, [44]={npc="Impsy", tgt="Impsy"}, [45]={hint="Bring a total of 6 Voodoo Feathers from the trolls in sunken temple."}, [46]={npc="Impsy", tgt="Impsy"}, [47]={npc="Impsy", tgt="Impsy"}, [48]={hint="Impsy in Felwood has asked that you bring him three Flawless Fel Essences originating from three distinct locations."}, [49]={npc="Impsy", tgt="Impsy"}, [50]={npc="Impsy", tgt="Impsy", desc="Kroshius is in northern Felwood. You need a group."}, [51]={hint="Search Shatter Scar Vale in Felwood for the remains of Kroshius. When you locate the remains, use the Fel Fire near them and await Kroshius' return. When the infernal has awoken, slay him and take from his corpse Kroshius' Infernal Core.", desc="Kroshius is in northern Felwood. You need a group."}, [52]={npc="Niby the Almighty", tgt="Niby the Almighty", desc="Kroshius is in northern Felwood. You need a group."}}},
    ["04-50"] = {steps={[2]={npc="Pratt McGrubben", tgt="Pratt McGrubben"}, [3]={npc="Troyas Moonbreeze", tgt="Troyas Moonbreeze"}, [4]={npc="Troyas Moonbreeze", tgt="Troyas Moonbreeze"}, [5]={npc="Gregan Brewspewer", tgt="Gregan Brewspewer"}, [6]={npc="Rockbiter", tgt="Rockbiter"}, [7]={hint="Seek out Gregan Brewspewer in northern Feralas. From him, learn how you may acquire the Videre Elixir, then return to Donova Snowden in Winterspring."}, [8]={hint="Energize Troyas' Stave and find the Equinex Monolith.", desc="Further on, you can jump up to take a shortcut."}, [9]={npc="Shay Leafrunner", tgt="Shay Leafrunner"}, [10]={npc="Equinex Monolith", npcObj=true, desc="Use the staff in your bags."}, [11]={npc="Equinex Monolith", npcObj=true}, [12]={hint="Bring 10 Rage Scar Yeti Hides to Pratt McGrubben at Feathermoon Stronghold, Feralas."}, [13]={npc="Pristine Yeti Hide", npcObj=true, tag="Optional", desc="If a Pristine Yeti Hide drops while killing yetis, right-click it to accept."}, [14]={npc="Pratt McGrubben", tgt="Pratt McGrubben"}, [15]={npc="Pratt McGrubben", tgt="Pratt McGrubben", tag="Optional"}, [16]={npc="Troyas Moonbreeze", tgt="Troyas Moonbreeze"}}},
    ["04-51"] = {steps={[1]={bind="Astranaar", desc="If your hearthstone is on cooldown, fly from Feathermoon Stronghold to Astranaar (via Auberdine), then walk north into Felwood."}, [2]={npc="Arathandris Silversky", tgt="Arathandris Silversky"}, [3]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [4]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [5]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [6]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [7]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [8]={npc="Taronn Redfeather", tgt="Taronn Redfeather"}, [9]={npc="Donova Snowden", tgt="Donova Snowden", desc="Return to Astranaar and fly to Talonbranch Glade, then head north through Timbermaw Hold into Winterspring."}, [10]={npc="Donova Snowden", tgt="Donova Snowden"}, [11]={npc="Donova Snowden", tgt="Donova Snowden"}, [12]={npc="Donova Snowden", tgt="Donova Snowden"}, [13]={desc="Kill furbolgs around 32, 36 in the Winterfall camp."}, [14]={npc="Gregor Greystone", tgt="Gregor Greystone"}, [15]={npc="Gregor Greystone", tgt="Gregor Greystone"}, [16]={desc="You'll connect through Talrendis Point."}, [17]={npc="Liv Rizzlefix", tgt="Liv Rizzlefix"}, [18]={npc="Islen Waterseer", tgt="Islen Waterseer"}, [19]={npc="Islen Waterseer", tgt="Islen Waterseer"}, [21]={npc="Alchemist Pestlezugg", tgt="Alchemist Pestlezugg"}, [22]={text="After drinking the Videre Elixir, stay dead and find the quest NPC as a ghost."}, [23]={npc="Gaeriyan", tgt="Gaeriyan"}, [24]={npc="Gaeriyan", tgt="Gaeriyan"}, [25]={text="Return to your corpse and resurrect."}, [26]={npc="A Conspicuous Gravestone", npcObj=true}, [27]={npc="A Conspicuous Gravestone", npcObj=true}, [28]={npc="Tran'rek", tgt="Tran'rek"}, [29]={npc="Alchemist Pestlezugg", tgt="Alchemist Pestlezugg"}}},
    ["04-52"] = {name="Un'Goro Crater", steps={[2]={npc="Linken", tgt="Linken"}, [3]={npc="Linken", tgt="Linken"}, [4]={npc="J.D. Collie", tgt="J.D. Collie"}, [5]={npc="J.D. Collie", tgt="J.D. Collie"}, [6]={npc="Spraggle Frock", tgt="Spraggle Frock"}, [7]={npc="Hol'anyee Marshal", tgt="Hol'anyee Marshal", tag="Optional"}, [8]={hint="Collect 12 samples of Super Sticky Tar for Tran'rek in Gadgetzan."}, [9]={npc="Krakle", tgt="Krakle"}, [10]={hint="Collect 9 samples of Un'Goro Ash from the fire elementals around the volcano in Un'Goro Crater, and return them to Liv Rizzlefix in Ratchet."}, [11]={hint="Krakle in Un'Goro Crater wants you to find the hottest area of Fire Plume Ridge."}, [12]={hint="Bring a Gorishi Scent Gland and 5 Un'Goro Soil samples to Alchemist Pestlezugg in Gadgetzan.", tag="Optional", desc="This is a dedicated detour with no other objectives nearby. Skip it if you're in a hurry."}, [13]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [14]={npc="Krakle", tgt="Krakle"}, [15]={npc="Krakle", tgt="Krakle"}, [16]={npc="Ringo", tgt="Ringo", desc="Escort quest: in a group, wait until everyone is at the same step before accepting, and turn off auto-accept."}, [17]={npc="Ringo", tgt="Ringo"}, [18]={hint="Lead Ringo to Spraggle Frock at Marshal's Refuge.", tag="Escort", desc="Lead Ringo back to Marshal's Refuge. He'll pass out along the way; use Spraggle's Canteen on him when he does."}, [19]={npc="Spraggle Frock", tgt="Spraggle Frock"}, [20]={npc="A-Me 01", tgt="A-Me 01"}, [21]={npc="A-Me 01", tgt="A-Me 01"}, [22]={hint="Find a Mithril Casing and return to A-Me 01 in Un'Goro Crater.", desc="Buy the mithril casing at the auction house beforehand, or have an engineer make it."}, [23]={npc="A-Me 01", tgt="A-Me 01"}, [24]={hint="Bring U'cha's Pelt to Torwa Pathfinder at the entrance of Un'Goro Crater."}, [25]={npc="A-Me 01", tgt="A-Me 01"}, [26]={hint="Escort A-Me 01 back to Karna Remtravel in Un'Goro Crater.", tag="Escort", desc="Escort A-Me 01 back to Karna 