nik", tag="Optional"}, [57]={npc="High Explorer Magellas", tgt="High Explorer Magellas", tag="Optional"}, [58]={npc="Royal Historian Archesonus", tgt="Royal Historian Archesonus"}, [59]={npc="Royal Historian Archesonus", tgt="Royal Historian Archesonus"}, [60]={npc="Royal Historian Archesonus", tgt="Royal Historian Archesonus"}, [61]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [62]={hint="Collect 8 Bloodcap and 8 Gorishi Stings, and return to Torwa Pathfinder in Un'Goro Crater."}, [63]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [64]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [65]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [66]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [67]={hint="Retrieve a Putrid Vine from the guardian at the bottom of the Sunken Temple and return to Torwa Pathfinder."}, [68]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}}},
    ["04-54"] = {steps={[1]={text="If you've unlocked Morgan's Vigil, fly there directly from Ironforge. If not, fly to Lakeshire and follow the road north into the Burning Steppes; Morgan's Vigil is right by the entrance.", tag="Flight path locked. Travel there on foot the first time."}, [2]={node="Morgan's Vigil"}, [3]={npc="Oralius", tgt="Oralius"}, [4]={npc="Oralius", tgt="Oralius"}, [5]={npc="Helendis Riverhorn", tgt="Helendis Riverhorn", tag="Optional"}, [6]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil"}, [7]={npc="Maxwort Uberglint", tgt="Maxwort Uberglint"}, [8]={hint="Venture to the Ruins of Thaurissan in the Burning Steppes and recover information from the Thaurissan Relics. Return to Royal Historian Archesonus when you have recovered the information."}, [9]={hint="Bring the Tablet Transcript to Maxwort Uberglint in the Burning Steppes."}, [10]={hint="Slay 15 Firegut Ogre-Mages, 7 Firegut Ogres, and 7 Firegut Ogre Brutes, and return to Oralius when you are finished."}, [11]={hint="Bring 8 Broodling Essence and the Draco-Incarcinatrix 900 to Tinkee Steamboil at the Flame Crest in the Burning Steppes."}, [12]={hint="Slay 15 Black Broodlings, 10 Black Dragonspawn, 4 Black Wyrmkin and 1 Black Drake. Return to Helendis Riverhorn when the task is complete.", tag="Later, on the way"}, [13]={npc="Cyrus Therepentous", tgt="Cyrus Therepentous", tag="Optional"}, [14]={npc="Cyrus Therepentous", tgt="Cyrus Therepentous", tag="Optional"}, [15]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil"}, [16]={npc="Maxwort Uberglint", tgt="Maxwort Uberglint"}, [17]={npc="Oralius", tgt="Oralius"}, [18]={npc="Oralius", tgt="Oralius", tag="Optional"}, [19]={npc="Helendis Riverhorn", tgt="Helendis Riverhorn", tag="Optional"}, [20]={npc="Helendis Riverhorn", tgt="Helendis Riverhorn", tag="Optional"}, [21]={hint="Find Gor'tesh, somewhere to the west of Dreadmaul Rock. Kill Gor'tesh and then take Gor'tesh's Lopped Off Head back to Oralius in Burning Steppes.", tag="Optional"}, [22]={hin