    ["04-55"] = {steps={[1]={desc="If you've unlocked Chillwind Camp, fly straight there and skip the next step. If Aerie Peak isn't on your flight map, fly to Southshore and run east to Aerie Peak the same way as on the Hinterlands trip."}, [2]={text="From Aerie Peak, take the mountain road north into the southeast corner of the Western Plaguelands (65.30, 86.80), then follow the road west to Chillwind Camp.", tag="Flight path locked. Travel there on foot the first time."}, [3]={node="Chillwind Camp"}, [4]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist"}, [5]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist"}, [6]={npc="Argent Officer Pureheart", tgt="Argent Officer Pureheart"}, [7]={npc="Argent Officer Pureheart", tgt="Argent Officer Pureheart"}, [8]={npc="Argent Officer Pureheart", tgt="Argent Officer Pureheart"}, [9]={npc="Argent Officer Pureheart", tgt="Argent Officer Pureheart", desc="A letter delivery quest; turn it in near the entrance to Mount Hyjal."}, [10]={npc="Flint Shadowmore", tgt="Flint Shadowmore"}, [11]={npc="Flint Shadowmore", tgt="Flint Shadowmore", tag="Optional"}, [12]={hint="Kill 10 Skeletal Flayers and 10 Slavering Ghouls in Sorrow Hill."}, [13]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist"}, [14]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist"}, [15]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist"}, [16]={npc="High Priestess MacDonnell", tgt="High Priestess MacDonnell"}, [17]={npc="High Priestess MacDonnell", tgt="High Priestess MacDonnell"}, [18]={hint="Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it."}, [19]={hint="Go to Felstone Field in Western Plaguelands to locate and defeat the Cauldron Lord present there. It may have a key that will allow access to the cauldron. You must have the Empty Felstone Field Bottle with you to secure a sample of the poisons used inside the cauldron."}, [20]={npc="Scourge Cauldron", npcObj=true}, [21]={npc="Scourge Cauldron", npcObj=true}, [22]={npc="Janice Felstone", tgt="Janice Felstone"}, [23]={npc="Janice's Parcel", npcObj=true}, [24]={npc="Janice's Parcel", npcObj=true}, [25]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist"}, [26]={npc="High Priestess MacDonnell", tgt="High Priestess MacDonnell"}, [27]={npc="High Priestess MacDonnell", tgt="High Priestess MacDonnell"}, [28]={hint="Go to Dalson's Tears in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Dalson's Tears Bottle with you to secure a sample of the poisons used inside the cauldron."}, [29]={npc="Scourge Cauldron", npcObj=true}, [30]={npc="Scourge Cauldron", npcObj=true}, [31]={npc="High Priestess MacDonnell", tgt="High Priestess MacDonnell"}, [32]={npc="High Priestess MacDonnell", tgt="High Priestess MacDonnell"}, [33]={npc="Nathaniel Dumah", tgt="Nathaniel Dumah"}, [34]={hint="Go to the Writhing Haunt in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Writhing Haunt Bottle with you to secure a sample of the poisons used inside the cauldron."}, [35]={npc="Scourge Cauldron", npcObj=true}, [36]={npc="Scourge Cauldron", npcObj=true}, [37]={npc="Mulgris Deepriver", tgt="Mulgris Deepriver"}, [38]={hint="Destroy 8 Diseased Wolves, and then return to Mulgris Deepriver at the Writhing Haunt, Western Plaguelands."}, [39]={npc="Mulgris Deepriver", tgt="Mulgris Deepriver"}, [40]={npc="Mulgris Deepriver", tgt="Mulgris Deepriver"}, [41]={hint="Destroy 8 Diseased Grizzlies, and then return to Mulgris Deepriver at the Writhing Haunt, Western Plaguelands."}, [42]={npc="Mulgris Deepriver", tgt="Mulgris Deepriver"}, [43]={npc="Mulgris Deepriver", tgt="Mulgris Deepriver"}, [44]={text="Follow the road to this spot."}, [45]={text="Set your hearth in the Aerie Peak inn (13.80, 41.60).", bind="Aerie Peak"}, [46]={npc="Cortello's Treasure", npcObj=true}, [47]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist"}, [48]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist"}, [49]={hint="Collect 20 Minion's Scourgestones and bring them to High Priest Thel'danis in the Western Plaguelands."}, [50]={npc="High Priest Thel'danis", tgt="High Priest Thel'danis"}, [51]={npc="High Priest Thel'danis", tgt="High Priest Thel'danis"}, [52]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist"}, [53]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist", desc="Turn it in to get the Mightstone."}, [54]={hint="Bring the voodoo feathers to Ashlam Valorfist.", desc="Turn it in to get the Mightstone."}, [55]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist", desc="Turn it in to get the Mightstone."}, [56]={bind="Aerie Peak"}}},
    ["04-56"] = {steps={[1]={text="From Aerie Peak, take the mountain road north into the Western Plaguelands, then head east across the Thondroril River into the Eastern Plaguelands. Tirion Fordring is in the cabin right by the entrance."}, [2]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [3]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [4]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [5]={hint="Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete."}, [6]={hint="Slay 30 Plaguebats and return to Tirion Fordring."}, [7]={hint="Seek out the Carrion Grubs and Devourers of the region. Slay them and harvest their meat. Return to Tirion Fordring when you have gathered 15 Slabs of Carrion Worm Meat."}, [8]={npc="Pamela Redpath", tgt="Pamela Redpath"}, [9]={npc="Pamela Redpath", tgt="Pamela Redpath"}, [10]={hint="Find Pamela's doll.", desc="In the ruined houses of Darrowshire, collect the head, left side and right side, then right-click to combine them."}, [11]={npc="Pamela Redpath", tgt="Pamela Redpath"}, [12]={npc="Pamela Redpath", tgt="Pamela Redpath"}, [13]={npc="Pamela Redpath", tgt="Pamela Redpath"}, [14]={npc="Duke Nicholas Zverenhoff", tgt="Duke Nicholas Zverenhoff"}, [15]={node="Light's Hope Chapel"}, [16]={npc="Carlin Redpath", tgt="Carlin Redpath"}, [17]={npc="Carlin Redpath", tgt="Carlin Redpath", tag="Optional"}, [18]={npc="Caretaker Alen", tgt="Caretaker Alen"}, [19]={hint="Free 15 Darrowshire Spirits and return to Carlin Redpath.", tag="Optional", desc="This is a dedicated detour with no other objectives nearby. Skip it if you're in a hurry."}, [20]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [21]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [22]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [23]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [24]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [25]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [26]={hint="Travel to the Undercroft - at the southernmost section of the Eastern Plaguelands - and recover Taelan's Hammer. Return to Tirion Fordring upon completion of your objective."}, [27]={hint="Bring Zaeldarr's Head to Caretaker Alen at Light's Hope Chapel."}, [28]={npc="Torn Scroll", npcObj=true}, [29]={hint="Scour the Eastern Plaguelands for clues as to the \"Blightcaller\" and the missing SI:7 agents. If you find any SI:7 Insignias, return them to Flint Shadowmore at Chillwind Camp.", tag="Optional"}, [30]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [31]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [32]={npc="Caretaker Alen", tgt="Caretaker Alen"}, [33]={npc="Carlin Redpath", tgt="Carlin Redpath", tag="Optional"}}},
    ["04-53"] = {steps={[1]={desc="You'll connect through Chillwind Camp or Aerie Peak; if Southshore isn't on your flight map, fly to Stormwind as usual and take the boat to Auberdine from the harbor."}, [2]={desc="There's a boat to Auberdine right at the Southshore dock, which is faster than flying to Stormwind and changing boats. If you fly to Stormwind instead, board at the Stormwind harbor."}, [4]={hint="Donova Snowden in Winterspring wants you to kill 8 Winterfall Pathfinders, 8 Winterfall Den Watchers, and 8 Winterfall Totemics."}, [5]={hint="Salfa wants you to kill 8 Winterfall Shaman, 8 Winterfall Den Watchers, and 8 Winterfall Ursa. Salfa is located just outside the entrance to Timbermaw Hold in Winterspring.", tag="Unverified"}, [6]={npc="Empty Firewater Flask", npcObj=true, desc="Right-click Empty Firewater Flask in your bags to start the quest."}, [7]={npc="Donova Snowden", tgt="Donova Snowden"}, [8]={npc="Donova Snowden", tgt="Donova Snowden"}, [9]={npc="Donova Snowden", tgt="Donova Snowden"}, [10]={npc="Donova Snowden", tgt="Donova Snowden"}, [11]={npc="Donova Snowden", tgt="Donova Snowden", desc="Exploring Darkwhisper Gorge gets done on the way into Mount Hyjal at the next stop; turn it in before going back to Winterspring and on to Moonglade. Turn it in before going back to Winterspring and on to Moonglade."}, [12]={hint="Collect 10 Moontouched Feathers from Winterspring, then return to Erelas Ambersky in Rut'theran Village."}, [13]={npc="Salfa", tgt="Salfa", tag="Unverified"}, [14]={npc="Deadwood Cauldron", npcObj=true}, [15]={npc="Deadwood Cauldron", npcObj=true}, [16]={desc="From the Deadwood Cauldron, head south to the Talonbranch Glade flight point (62.49, 24.24) and take off from there; you'll change flights at Auberdine."}, [17]={npc="Erelas Ambersky", tgt="Erelas Ambersky"}, [18]={npc="Erelas Ambersky", tgt="Erelas Ambersky"}, [19]={npc="Daryn Lightwind", tgt="Daryn Lightwind"}, [21]={npc="Harlo Wigglesworth", tgt="Harlo Wigglesworth"}, [22]={npc="Wynd Nightchaser", tgt="Wynd Nightchaser"}, [23]={npc="Wynd Nightchaser", tgt="Wynd Nightchaser"}, [24]={npc="Jaron Stoneshaper", tgt="Jaron Stoneshaper"}, [25]={npc="Jaron Stoneshaper", tgt="Jaron Stoneshaper"}, [26]={npc="Jaron Stoneshaper", tgt="Jaron Stoneshaper"}, [27]={npc="Jaron Stoneshaper", tgt="Jaron Stoneshaper"}, [28]={hint="Use Jaron's Pick to find the four Highborne Relic Fragments. Bring them to Aurora Skycaller in Eastern Plaguelands."}, [29]={npc="Donova Snowden", tgt="Donova Snowden"}, [30]={npc="Damaged Crate", npcObj=true}, [31]={npc="Damaged Crate", npcObj=true}, [32]={npc="Jaron's Wagon", npcObj=true}, [33]={npc="Jaron's Wagon", npcObj=true}, [34]={hint="Pick up Jaron's Supplies from the snow, then find the wildkin that stole the amulet Jaron spoke of."}, [35]={npc="Ranshalla", tgt="Ranshalla"}, [36]={npc="Ranshalla", tgt="Ranshalla"}, [37]={hint="Protect Ranshalla while she attempts to reactivate the Altar of Elune. Report your findings to Erelas Ambersky in Rut'theran Village."}}},
    ["04-57"] = {danger={[1]="Ghansurok (level 61 elite chimaera) patrols from the tainted hibiscus to Kaylaena's workshop (about x55-62.5, y61.5-72.2); check its position when hitting bushes and when going back to the workshop.", [2]="Celastrus the Bitter (level 57 elite) wanders around the tainted hibiscus; watch for him when hitting bushes.", [3]="The bone pile summons a level 58 elite slime; don't click it a second time without a group."}, grind={[1]={note="The north part of the Felblood Scar; all of Felflick's quests are fought here."}}, supply={[1]={}}, steps={[1]={text="From Ranshalla go south into Darkwhisper Gorge and follow the gorge west to the end to enter Mount Hyjal. There's an elite frost giant at the gorge mouth and elite demons inside; stick to the road and don't stop.", tag="Flight path locked. Travel there on foot the first time., Unverified"}, [2]={hint="Follow Donova Snowden's instructions, then report back.", tag="Unverified", desc="Going through Mount Hyjal by the gorge completes it, so no extra detour is needed. It counts once the quest log shows it as complete."}, [3]={text="Enter Mount Hyjal at the southeast corner and follow the road west.", tag="Unverified"}, [4]={npc="Quintus Wainworth", tgt="Quintus Wainworth"}, [5]={npc="Quintus Wainworth", tgt="Quintus Wainworth"}, [6]={npc="Loose Cog", npcObj=true, desc="A cog on the ground by the road; right-click to pick it up and start the quest."}, [7]={npc="Ketharas", tgt="Ketharas", tag="Optional"}, [8]={npc="Ketharas", tgt="Ketharas"}, [9]={npc="Ketharas", tgt="Ketharas"}, [10]={npc="Ketharas", tgt="Ketharas"}, [11]={npc="Ketharas", tgt="Ketharas"}, [12]={npc="Ketharas", tgt="Ketharas"}, [13]={hint="Rescue 12 Hyjal Owl Eggs and bring them to Ketharas."}, [14]={hint="Collect 10 Untainted Seeds for Ketharas."}, [15]={npc="Ketharas", tgt="Ketharas"}, [16]={npc="Ketharas", tgt="Ketharas"}, [17]={npc="Ketharas", tgt="Ketharas"}, [18]={npc="Ketharas", tgt="Ketharas"}, [19]={hint="Collect 2 Hyjal Venison Cuts from untainted Hyjal Stags and 6 Scarlet Dart Tubers for the hermit's stew."}, [20]={hint="Plant the Enchanted Seeds near the Ruined Ballista, the Ruined Catapult, and the Ruined Flying Machine.", tag="Unverified", desc="The ballista, catapult and flying machine wrecks each count as one objective, and you have to plant all three."}, [21]={npc="Ketharas", tgt="Ketharas"}, [22]={npc="Ketharas", tgt="Ketharas"}, [23]={npc="Ketharas", tgt="Ketharas"}, [24]={hint="Bury the remains at Ketharas' shrine.", tag="Unverified", desc="The coordinates are the approximate location reported by players."}, [25]={npc="Ketharas", tgt="Ketharas"}, [26]={npc="Ketharas", tgt="Ketharas"}, [27]={node="Tainted Foothills", desc="Follow the road west; the flight point is beside the Ancients' Outpost."}, [28]={npc="Fraxinus", tgt="Fraxinus"}, [29]={npc="Hyacinth", tgt="Hyacinth"}, [30]={npc="Hyacinth", tgt="Hyacinth"}, [31]={npc="Thylaen", tgt="Thylaen", tag="Group, Optional", desc="The target is a level 57 elite; if you can't beat it solo, don't pick it up."}, [32]={hint="Collect 6 samples of Untainted Soil from around the foothills of Mount Hyjal."}, [33]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [34]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [35]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="When you go to Everlook later, find Nami for the parts."}, [36]={hint="Destroy 15 Tainted Shrubbery for Kaylaena Springwhisper at the workshop in the Tainted Foothills.", desc="The same hibiscus bushes also drop the leaves that stop bleeding; kill them for both quests together. Turn it in at the workshop when you deliver the crate."}, [37]={hint="Collect 12 Verdant Leaves from Tainted Shrubbery in the foothills of Mount Hyjal."}, [38]={hint="Find and destroy Celastrus the Bitter, and return to Thylaen with its broken frond.", tag="Group, Optional"}, [39]={npc="Hyacinth", tgt="Hyacinth"}, [40]={npc="Hyacinth", tgt="Hyacinth"}, [41]={npc="Thylaen", tgt="Thylaen", tag="Group, Optional"}, [42]={npc="Hyacinth", tgt="Hyacinth"}, [43]={hint="Apply the poultice to Fraxinus."}, [44]={npc="Fraxinus", tgt="Fraxinus"}, [45]={npc="Fraxinus", tgt="Fraxinus", tag="Group, Optional", desc="The target, Sunderbark, is a level 56 elite ancient; do it when you have a group. If you haven't grouped up, skip steps \"Accept The Dying Ancients\", \"Do The Dying Ancients\", \"Turn in The Dying Ancients\"."}, [46]={npc="Fraxinus", tgt="Fraxinus"}, [47]={npc="Curious Crow", tgt="Curious Crow"}, [48]={npc="Curious Crow", tgt="Curious Crow"}, [49]={npc="Curious Crow", tgt="Curious Crow"}, [50]={npc="Felflick", tgt="Felflick"}, [51]={npc="Felflick", tgt="Felflick"}, [52]={hint="Slay 12 Ashen Acolytes.", desc="The notes drop from the same acolytes, so fight them for both quests."}, [53]={hint="Find 12 Fel Ash Experimentation Notes."}, [54]={npc="Felflick", tgt="Felflick"}, [55]={npc="Felflick", tgt="Felflick"}, [56]={hint="Gather 8 Fel-Slime Crystals and 1 Pristine Fel-Slime Crystal."}, [57]={npc="Felflick", tgt="Felflick"}, [58]={npc="Felflick", tgt="Felflick"}, [59]={npc="Felflick", tgt="Felflick"}, [60]={hint="Retrieve the bones of Frezzlie Popwhiz, Tyaeha Darkoath and Dazka Shadowsleep."}, [61]={hint="Slay Brashann Grimdark and search his body for his soulstone."}, [62]={npc="Felflick", tgt="Felflick"}, [63]={npc="Felflick", tgt="Felflick"}, [64]={npc="Felflick", tgt="Felflick"}, [65]={npc="Bone Pile", npcObj=true, desc="Throw the warlock bones onto the bone pile beside the slime pool."}, [66]={npc="Bone Pile", npcObj=true, tag="Group, Optional", desc="It summons a level 58 elite slime. If you haven't grouped up, skip steps \"Accept Amalgamated Marrow\"-\"Do Amalgamated Marrow\", \"Turn in Amalgamated Marrow\"-\"Accept A Revenge Now Bitter\", \"Turn in A Revenge Now Bitter\"."}, [67]={hint="Slay the Awakened Fel Ash Slime.", tag="Group, Optional"}, [68]={npc="Velician", tgt="Velician"}, [69]={npc="Felflick", tgt="Felflick", tag="Group, Optional"}, [70]={npc="Felflick", tgt="Felflick", tag="Group, Optional"}, [71]={npc="Curious Crow", tgt="Curious Crow"}, [72]={npc="Curious Crow", tgt="Curious Crow"}, [73]={npc="Curious Crow", tgt="Curious Crow", tag="Group, Optional"}, [74]={npc="Curious Crow", tgt="Curious Crow"}, [75]={npc="Curious Crow", tgt="Curious Crow"}, [76]={npc="Curious Crow", tgt="Curious Crow"}, [77]={hint="Gather 8 Fel-Slime Ooze."}, [78]={hint="Collect 10 Prickly Pinecones under healthy trees."}, [79]={npc="Curious Crow", tgt="Curious Crow"}, [80]={npc="Curious Crow", tgt="Curious Crow"}, [81]={npc="Curious Crow", tgt="Curious Crow"}, [82]={hint="Use the pinecones to destroy the Ashen Reign workstations.", tag="Unverified"}, [83]={npc="Curious Crow", tgt="Curious Crow"}, [84]={npc="Curious Crow", tgt="Curious Crow", desc="Turn it in at Elderwild to the west at the next stop."}, [85]={hint="Hunt down and destroy the corrupted ancient Sunderbark, then plant a seed in his remains.", tag="Group, Optional", desc="On the way back east to the Hermit's Cave."}, [86]={npc="Ketharas", tgt="Ketharas"}, [87]={npc="Ketharas", tgt="Ketharas"}, [88]={npc="Fraxinus", tgt="Fraxinus", tag="Group, Optional"}, [90]={npc="Nami", tgt="Nami", desc="The follow-up crate is time-limited, so pick it up after you're back from Moonglade."}, [91]={npc="Jaron Stoneshaper", tgt="Jaron Stoneshaper", desc="From Everlook follow the road west a short way to Starfall Village."}, [92]={text="From Starfall Village ride southwest along the road to the hot spring and find Donova.", tag="Unverified"}, [93]={npc="Donova Snowden", tgt="Donova Snowden"}, [94]={desc="Ride back from the hot spring to the Everlook flight point and fly (the Moonglade flight path was unlocked at stop 49). If your Timbermaw reputation is already neutral, ride north from the hot spring to the Timbermaw Hold entrance (27.70, 34.50); going through the cave to the Moonglade exit is closer; if you haven't unlocked the Moonglade flight path, take this route too, and unlock the flight path first when you arrive (48.10, 67.34); below neutral you'll be attacked. Druids can use Teleport: Moonglade directly; after arriving, go to the regular flight point (48.10, 67.34) and unlock it so you can fly back. If you haven't unlocked the Moonglade flight path, take this route too, and unlock the flight path first when you arrive (48.10, 67.34). Below neutral reputation you'll be attacked. Druids can use Teleport: Moonglade directly; after arriving, go to the regular flight point (48.10, 67.34) and unlock it so you can fly back."}, [95]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [96]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [97]={npc="Orokai", tgt="Orokai"}, [98]={npc="Orokai", tgt="Orokai"}, [99]={hint="Speak with Orokai when you are ready to see what he learned from the Faintly Glowing Branch."}, [100]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [101]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [102]={desc="Take off from the regular Moonglade flight point (48.10, 67.34) and get off at Everlook to pick up the crate."}, [103]={npc="Nami", tgt="Nami", desc="The batteries in the crate fail after about two hours, so deliver it straight to Kaylaena from the flight point."}, [104]={desc="From the flight point ride straight north to Kaylaena's workshop and deliver the crate first."}}},
    ["04-58"] = {danger={[1]="Ghansurok (level 61 elite chimaera) patrols east of the Shrine of Aviana; watch for him when fighting harpies."}, supply={[1]={}, [2]={}}, steps={[1]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="From the flight point ride straight north to the workshop and deliver the crate first."}, [2]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [3]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="The materials are in the Horde camp wreckage at Dae'gun to the north; pick them up when you pass later."}, [4]={npc="Ketharas", tgt="Ketharas", desc="Ride southeast from the workshop back to the Hermit's Cave."}, [5]={npc="Ketharas", tgt="Ketharas"}, [6]={npc="Ketharas", tgt="Ketharas"}, [7]={npc="Skylord Omnuron", tgt="Skylord Omnuron", desc="Ride northwest from the Hermit's Cave to the Shrine of Aviana."}, [8]={npc="Skylord Omnuron", tgt="Skylord Omnuron"}, [9]={npc="Skylord Omnuron", tgt="Skylord Omnuron"}, [10]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [11]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [12]={hint="Slay 18 Wormwing harpies on Mount Hyjal and bring their feathers to Phoebe Highfeather."}, [13]={hint="Collect 8 Tarnished Highfeather Bangles from Wormwing Harpy nests."}, [14]={hint="Find the Jewel of the Horizon in the Wormwing harpy nests on Mount Hyjal and bring it to Ketharas."}, [15]={hint="Slay Zarrat Wormwing and return Omnuron's Spear."}, [16]={npc="Corrupted Growth", npcObj=true, desc="Right-click the corrupted growth on the tree to pick up the quest."}, [17]={hint="Find and remove 6 Corrupted Knots from the trees nearby.", tag="Unverified"}, [18]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [19]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [20]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [21]={npc="Skylord Omnuron", tgt="Skylord Omnuron"}, [22]={npc="Curious Crow", tgt="Curious Crow"}, [23]={npc="Curious Crow", tgt="Curious Crow", desc="You can only do it on the bridge at the Cradle of Tranquility to the north, so carry it with you for now."}, [24]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring", desc="Follow the foothills west."}, [25]={hint="Locate a sturdy branch capable of reaching Fenwick Togglespring."}, [26]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring"}, [27]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring"}, [28]={hint="Break the tree branch to free Fenwick Togglespring."}, [29]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring"}, [30]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring"}, [31]={npc="Personal Survival Pack", tgt="Personal Survival Pack"}, [32]={npc="Personal Survival Pack", tgt="Personal Survival Pack"}, [33]={hint="Wait until you can safely open the Personal Survival Pack."}, [34]={npc="Personal Survival Pack", tgt="Personal Survival Pack"}, [35]={npc="Brerufa", tgt="Brerufa"}, [36]={hint="Defeat 9 Deadwood Den Guardians and return to Brerufa."}, [37]={npc="Brerufa", tgt="Brerufa"}, [38]={npc="Brerufa", tgt="Brerufa", tag="Optional, Unverified", desc="Pick it up only if you can see the quest. Only turn it in if you already have 8 strings of beads; no need to farm more."}, [39]={npc="Brerufa", tgt="Brerufa"}, [40]={npc="Osi Mistpaw", tgt="Osi Mistpaw"}, [41]={npc="Osi Mistpaw", tgt="Osi Mistpaw"}, [42]={hint="Gather 30 Bear Berries from Hyjal and return to Osi Mistpaw."}, [43]={npc="Osi Mistpaw", tgt="Osi Mistpaw"}, [44]={npc="Osi Mistpaw", tgt="Osi Mistpaw"}, [45]={hint="Find and speak with Elder Mistpaw and Elder Pinespeaker within Barkskin Burrow."}, [46]={npc="Elder Mistpaw", tgt="Elder Mistpaw"}, [47]={npc="Elder Mistpaw", tgt="Elder Mistpaw"}, [48]={npc="Elder Pinespeaker", tgt="Elder Pinespeaker"}, [49]={npc="Suma Mossmane", tgt="Suma Mossmane"}, [50]={npc="Fennar Mossmane", tgt="Fennar Mossmane", tag="Optional, Unverified", desc="Pick it up only if you can see the quest (requires Barkskin cave reputation)."}, [51]={npc="Fennar Mossmane", tgt="Fennar Mossmane", tag="Optional, Unverified", desc="Pick it up only if you can see the quest (requires Barkskin cave reputation). Fill the waterskin at the pond outside the Deadwood den."}, [52]={hint="Collect 10 Dried Hanging Herbs from around Barkskin Burrow and return them to Fennar Mossmane.", tag="Optional, Unverified"}, [53]={npc="Elder Mistpaw", tgt="Elder Mistpaw", tag="Optional, Unverified", desc="Pick it up only if you can see the quest. You can only turn it in once your Barkskin cave reputation reaches neutral."}, [54]={hint="Bring 5 owl bodies to Elder Pinespeaker in Barkskin Burrow in Hyjal."}, [55]={hint="Gather 12 clumps of Moonveil Moss and return to Suma Mossmane."}, [56]={hint="Defeat 8 Deadwood Totemics and 8 Deadwood Fel-Tenders and return to Elder Pinespeaker."}, [57]={hint="Fill a waterskin provided by Fennar Mossmane at the pond outside of the Deadwood Furbolg den.", tag="Optional, Unverified"}, [58]={npc="Barkskin Matriarch", tgt="Barkskin Matriarch", tag="Unverified"}, [59]={hint="Recover a Deadwood Key from a Deadwood Warden and return to the Barkskin Cage."}, [60]={npc="Barkskin Matriarch", tgt="Barkskin Matriarch", tag="Unverified"}, [61]={npc="Barkskin Matriarch", tgt="Barkskin Matriarch", tag="Unverified"}, [62]={hint="Escort the Barkskin Matriarch out of Deadwood Den and return to Barkskin Burrow.", tag="Unverified", desc="An escort quest; when grouped, wait until everyone has accepted it before starting."}, [63]={npc="Brerufa", tgt="Brerufa"}, [64]={npc="Brerufa", tgt="Brerufa", tag="Optional, Unverified", desc="Only turn it in if you have 8 strings of beads."}, [65]={npc="Elder Pinespeaker", tgt="Elder Pinespeaker"}, [66]={npc="Elder Pinespeaker", tgt="Elder Pinespeaker"}, [67]={npc="Suma Mossmane", tgt="Suma Mossmane"}, [68]={npc="Fennar Mossmane", tgt="Fennar Mossmane", tag="Optional, Unverified"}, [69]={npc="Fennar Mossmane", tgt="Fennar Mossmane", tag="Optional, Unverified"}, [70]={npc="Elder Mistpaw", tgt="Elder Mistpaw", tag="Optional, Unverified", desc="Only turn it in once your reputation has reached neutral."}, [71]={npc="Elder Pinespeaker", tgt="Elder Pinespeaker", tag="Optional, Unverified", desc="Pick it up only if you can see the quest. You can only turn it in once your Barkskin cave reputation reaches friendly."}, [72]={npc="Elder Pinespeaker", tgt="Elder Pinespeaker", tag="Optional, Unverified", desc="Only turn it in once your reputation has reached friendly. If you don't have enough, keep it for now."}, [73]={npc="Eluneth", tgt="Eluneth", desc="Head north."}, [74]={npc="Veteran of the Third War", tgt="Veteran of the Third War"}, [75]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [76]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [77]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [78]={npc="Mirt", tgt="Mirt"}, [79]={npc="Hnaz Blunderflame", tgt="Hnaz Blunderflame", desc="Beside the Elderwild inn; the owl nests are in the valley to the south, to collect on the way when you return to Eluneth later."}, [80]={hint="Capture and return 6 Escaped Sheep."}, [81]={npc="Mirt", tgt="Mirt"}, [82]={npc="Embroidered Scabbard", npcObj=true, desc="The overlook west of Elderwild."}, [83]={npc="Embroidered Scabbard", npcObj=true}, [84]={hint="Use the Embroidered Scabbard to speak with the war veteran and hear his story at the overlook in Elderwild."}, [85]={npc="Veteran of the Third War", tgt="Veteran of the Third War"}, [86]={npc="Unmarked Grave", npcObj=true, desc="By the roadside heading east, right-click the unmarked grave to pick up the quest."}, [87]={npc="Galvinquam Leafsyre", tgt="Galvinquam Leafsyre"}, [88]={hint="Fill Galvinquam Leafsyre's drinking gourd at the waterfall ahead.", tag="Unverified", desc="Fill water with the empty gourd the quest gives you at the waterfall ahead, not beside Galvinquam."}, [89]={npc="Galvinquam Leafsyre", tgt="Galvinquam Leafsyre"}, [90]={npc="Galvinquam Leafsyre", tgt="Galvinquam Leafsyre", desc="Take the baggage to the Summit of Eternity."}, [91]={npc="Lisbael Highfeather", tgt="Lisbael Highfeather", desc="Turn it in at the Shrine of Aviana afterward."}, [92]={hint="Touch the Crow Effigy on the bridge overlooking the Cradle of Tranquility to call the Wild God, Jereman."}, [93]={npc="Jereman", tgt="Jereman"}, [94]={npc="Jereman", tgt="Jereman"}, [95]={npc="Jereman", tgt="Jereman"}, [96]={npc="Jereman", tgt="Jereman"}, [97]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [98]={hint="Make skunks leave the area around Johun's equipment without killing them.", tag="Unverified"}, [99]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [100]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [101]={hint="Return 9 Rustleaf Fox Tails to Johun \"Punchy\" Dillas in Hyjal."}, [102]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [103]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [104]={npc="Kala'th", tgt="Kala'th", desc="Head west."}, [105]={npc="Kala'th", tgt="Kala'th"}, [106]={hint="Dissuade stags from acting as predators."}, [107]={hint="Look through the burned buildings in the Cradle of Tranquility for 6 Metal Brackets and 30 Nails and return to Johun \"Punchy\" Dillas in Hyjal."}, [108]={npc="Kala'th", tgt="Kala'th"}, [109]={npc="Marrosis", tgt="Marrosis"}, [110]={npc="Marrosis", tgt="Marrosis"}, [111]={npc="Marrosis", tgt="Marrosis"}, [112]={hint="Eliminate 3 Forgotten Soldiers and 12 Fleshflay Raveners."}, [113]={hint="Search the area for the grave's missing contents."}, [114]={hint="Acquire a Drop of Stolen Life from the Scourge in the ruins on Mount Hyjal, then return to Ketharas."}, [115]={hint="Use the Survivor's Torch on the Bone Pile, then collect the Reanimator's Amulet."}, [116]={hint="Collect 20 Sun-Bleached Bones."}, [117]={hint="Retrieve 8 Watcher's Eyes for Eluneth."}, [118]={npc="Marrosis", tgt="Marrosis"}, [119]={npc="Eluneth", tgt="Eluneth"}, [120]={hint="Head south into the valley and collect owl feathers from their nests.", tag="Unverified", desc="A short way south of Eluneth; killing Hyjal owls drops them too. Return to Elderwild after collecting them."}, [121]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [122]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [123]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [124]={npc="Hnaz Blunderflame", tgt="Hnaz Blunderflame"}, [125]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [126]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [127]={npc="Daythor Brellan", tgt="Daythor Brellan"}, [128]={npc="Daythor Brellan", tgt="Daythor Brellan"}, [129]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [130]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [131]={npc="Daythor Brellan", tgt="Daythor Brellan"}}},
    ["04-60"] = {danger={[1]="Ghansurok (level 61 elite chimaera) wanders along the ridge south of Kaylaena's workshop.", [2]="Mazzogore (level 60 elite) patrols south of Dae'gun; go around him when fighting hounds.", [3]="Ve'han Talongrasp (level 60 elite) guards Nordrassil Lodge; don't get too close during the cultist quests."}, grind={[1]={mob="Felguard Sentry", note="The southern half of Dae'gun; pick up the abandoned supplies and Horde wreckage materials along the way."}, [2]={note="The cultist camp east of the Summit of Eternity; the summit quests are all fought here."}}, supply={[1]={}, [2]={}, [3]={}}, steps={[1]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas", desc="Head back east along the road."}, [2]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [3]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper"}, [4]={npc="Witherbeard", tgt="Witherbeard"}, [5]={npc="Yashiro", tgt="Yashiro"}, [6]={hint="Light the two bonfires in Dae'gun and return to Yashiro."}, [7]={text="After lighting the campfire to the southeast, keep going southeast to Renalard; first turn in Clever Creature, pick up the ashes and the fox quest, then clear Dae'gun once more on the way back.", tag="Unverified"}, [8]={npc="Renalard", tgt="Renalard"}, [9]={npc="Renalard", tgt="Renalard"}, [10]={npc="Renalard", tgt="Renalard"}, [11]={hint="Collect 8 Abandoned Supplies.", desc="Use the Tuft of Fox Fur you got from the quest to lure the demon away, then pick up 8 abandoned supplies. The supplies aren't beside Renalard."}, [12]={hint="Scavenge the remains of the Horde base and return 5 Frayed Wire, 5 Scrap Metal, and 5 Calcified Excrement to Kaylaena."}, [13]={hint="Retrieve 6 Ephemeral Essences for Elaena Moonwhisper."}, [14]={hint="Slay 12 Felguard Sentinels in Dae'gun."}, [15]={hint="Fetch a pinch of Azgalor's Ashes from the ruins of Dae'gun on Mount Hyjal."}, [16]={hint="Enter Dae'gun and locate a high vantage point, then report details to Johun.", tag="Unverified"}, [17]={npc="Yashiro", tgt="Yashiro", desc="After clearing Dae'gun, come back here to Yashiro to turn in."}, [18]={npc="Yashiro", tgt="Yashiro"}, [19]={hint="Fight your way through Dae'gun with Yashiro.", tag="Unverified", desc="Follow Yashiro as he clears the path; it's complete once you defeat Doomguard Xarkul at the end."}, [20]={npc="Yashiro", tgt="Yashiro", tag="Unverified", desc="Turn it in to Yashiro where the event ends, which isn't necessarily back at the start."}, [21]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper"}, [22]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper", tag="Group, Optional", desc="Both targets are level 60 elite demons. If you haven't grouped up, skip steps \"Accept Drawing Down the Malevolent\"-\"Accept As the Crow Flies\", \"Turn in As the Crow Flies\"."}, [23]={hint="Use the Eye of Endless Influence on Bethra'zel and Mazzogore to siphon their power, then deliver the killing blow.", tag="Group, Optional"}, [24]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper", tag="Group, Optional"}, [25]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper", tag="Group, Optional"}, [26]={npc="Witherbeard", tgt="Witherbeard"}, [27]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [28]={npc="Renalard", tgt="Renalard", desc="Head southeast."}, [29]={node="Summit of Eternity", tag="Unverified", desc="From Renalard go a short way up the mountain to the east and learn Fayran Elthas's flight path. Turn in the few quests you brought up the mountain first to lighten your quest log."}, [30]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [31]={npc="Tiala Whitemane", tgt="Tiala Whitemane", tag="Optional"}, [32]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [33]={npc="Sebelia", tgt="Sebelia", desc="Turn in the letter package in Everlook shortly, then do the mail chain."}, [34]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", tag="Unverified", desc="From the Summit of Eternity go down the mountain west past Renalard, then south to the workshop. If the mountain path is blocked, fly to the Tainted Foothills and ride north."}, [35]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [36]={hint="Turn the two gears and connect the two battery terminals on both sides of Kaylaena's Glaive Thrower."}, [37]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [38]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", tag="Group, Optional", desc="The Ghansurok you lure is a level 61 elite chimaera."}, [39]={hint="Walk to the ridge south of Kaylaena's workshop and find a way to make a loud distracting commotion to draw the chimaera Ghansurok in range to be attacked.", tag="Group, Optional", desc="Interact with the drum on the cliff south of the workshop and lure the chimaera into range of the blade-wheel thrower so the NPC operates it; don't pull it far away to fight it by force."}, [40]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", tag="Group, Optional"}, [41]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather", desc="From the workshop, walk a short way southwest to the Shrine of Aviana."}, [42]={npc="Ketharas", tgt="Ketharas", desc="Ride southeast from the shrine back to the Hermit's Cave."}, [43]={npc="Ketharas", tgt="Ketharas"}, [44]={npc="Ketharas", tgt="Ketharas"}, [45]={npc="Ketharas", tgt="Ketharas"}, [46]={desc="Ride west from the Hermit's Cave and take off from the Tainted Foothills flight point."}, [47]={npc="Innkeeper Vizzie", tgt="Innkeeper Vizzie"}, [48]={npc="Innkeeper Vizzie", tgt="Innkeeper Vizzie"}, [49]={hint="Find 4 pieces of Missing Mail in the hills north of Everlook and bring it back to Innkeeper Vizzie.", tag="Unverified"}, [50]={npc="Innkeeper Vizzie", tgt="Innkeeper Vizzie"}, [51]={npc="Innkeeper Vizzie", tgt="Innkeeper Vizzie", desc="Take the mail back to the top of Mount Hyjal to turn it in."}, [52]={desc="You'll connect through the Tainted Foothills."}, [53]={npc="Sebelia", tgt="Sebelia", tag="Unverified"}, [54]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [55]={npc="Toron Rockhoof", tgt="Toron Rockhoof"}, [56]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [57]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [58]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [59]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [60]={npc="Thisalee Crow", tgt="Thisalee Crow", tag="Group, Optional"}, [61]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [62]={hint="Find thorn seeds in the forests at the summit of Mount Hyjal and bring them back to Tiala Whitemane."}, [63]={hint="Reactivate the sentinel stones north, west, and south around the Blackthorne cultists.", tag="Unverified", desc="The north, west and south stones each count as one objective, and you have to visit all three."}, [64]={hint="Use the Staff of the Mountain on 10 members of the Blackthorne Pact on the Summit of Eternity to remove their wards and then kill them.", desc="The same cultists also count for End the Frenzy and Twisted Tools; use the staff first and then kill them, and do all three together."}, [65]={hint="Kill 10 Blackthorne Adepts and 10 Wild-branded Cultists."}, [66]={hint="Recover a Wicked Ritualist's Kris and a Recoiling Gnarlybark Staff from Blackthorne cultists."}, [67]={hint="Collect 5 Grand Hippogryph Feathers and 3 Oily Chimaera Hair for Marn."}, [68]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [69]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [70]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [71]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [72]={hint="Plant thorn seeds near the inn, the storage tower, and the grouping of trees at the loyalist druid camp.", tag="Unverified"}, [73]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [74]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [75]={npc="Thisalee Crow", tgt="Thisalee Crow", desc="After accepting it, first go to Marn to turn in Winds of Purification and pick up Archimonde's Pardon; do the two on the same trip."}, [76]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [77]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [78]={hint="Use the Enchanted Branch to release 5 wisps around Nordrassil.", tag="Unverified", desc="Free the wisp that's already beneath the roots, rather than summoning it with an item in the clearing. Do it on the same trip as Archimonde's Pardon."}, [79]={hint="Take Marn's incense and allow the smoke to ward the air around Archimonde's remains.", tag="Unverified"}, [80]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [81]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [82]={npc="Toron Rockhoof", tgt="Toron Rockhoof"}, [83]={desc="You'll connect through the Tainted Foothills and Everlook."}, [84]={npc="Erelas Ambersky", tgt="Erelas Ambersky"}, [85]={npc="Erelas Ambersky", tgt="Erelas Ambersky"}, [86]={text="Step into the portal in Rut'theran Village to Darnassus."}, [87]={npc="Arch Druid Fandral Staghelm", tgt="Arch Druid Fandral Staghelm"}, [88]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker"}}},
    ["04-59"] = {name="Western Plaguelands", steps={[1]={bind="Aerie Peak", desc="Only use your hearthstone if you're still bound to Aerie Peak and it's off cooldown. Otherwise take the boat backup: use the portal back to Rut'theran Village, fly to Auberdine, take the boat to Menethil Harbor, get off at Southshore, then fly to Chillwind Camp."}, [2]={desc="Skip this if you're already at Chillwind Camp. If the flight map doesn't list Chillwind Camp, walk north along the mountain road from Aerie Peak into Western Plaguelands and then west to Chillwind Camp."}, [3]={npc="High Priestess MacDonnell", tgt="High Priestess MacDonnell"}, [4]={npc="Flint Shadowmore", tgt="Flint Shadowmore", tag="Optional"}, [5]={npc="High Priestess MacDonnell", tgt="High Priestess MacDonnell"}, [6]={npc="Marlene Redpath", tgt="Marlene Redpath"}, [7]={npc="Marlene Redpath", tgt="Marlene Redpath"}, [8]={hint="Bring Joseph's Wedding Ring to Chromie."}, [9]={npc="Chromie", tgt="Chromie"}, [10]={npc="Chromie", tgt="Chromie"}, [11]={npc="Chromie", tgt="Chromie"}, [12]={hint="Bring the Annals of Darrowshire to Chromie in Andorhal."}, [13]={hint="Use the Temporal Displacer near one of Andorhal's silos and uncover Temporal Parasites."}, [14]={npc="Chromie", tgt="Chromie"}, [15]={npc="Chromie", tgt="Chromie"}, [16]={npc="Chromie", tgt="Chromie"}, [17]={desc="Andorhal has no flight point. Walk back south to Chillwind Camp first and fly from there."}, [18]={npc="Carlin Redpath", tgt="Carlin Redpath"}, [19]={npc="Carlin Redpath", tgt="Carlin Redpath", tag="Optional"}, [20]={npc="Carlin Redpath", tgt="Carlin Redpath"}, [21]={hint="Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective."}, [22]={hint="Kill Infiltrator Hameya. Use his key on the Mound of Dirt behind the Undercroft."}, [23]={npc="Aurora Skycaller", tgt="Aurora Skycaller"}, [24]={hint="Use the Empty Termite Jar on the Termite Mounds in Eastern Plaguelands. After you've gathered 100 Plagueland Termites, return to Nathaniel Dumah at Chillwind Camp in Western Plaguelands."}, [25]={hint="Bring the Skull of Horgus and the Shattered Sword of Marduk to Carlin Redpath at Light's Hope Chapel.", tag="Optional", desc="This is a dedicated detour with no other objectives nearby. Skip it if you're in a hurry."}, [26]={npc="Mound of Dirt", npcObj=true}, [27]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [28]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [29]={hint="Bring Davil's Libram and Redpath's Shield to Carlin Redpath."}, [30]={hint="Go to Gahrron's Withering in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Gahrron's Withering Bottle with you to secure a sample of the poisons used inside the cauldron."}, [31]={npc="Scourge Cauldron", npcObj=true}, [32]={npc="Scourge Cauldron", npcObj=true}, [33]={npc="Artist Renfray", tgt="Artist Renfray"}, [34]={npc="High Priestess MacDonnell", tgt="High Priestess MacDonnell"}, [35]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist"}, [36]={npc="Commander Ashlam Valorfist", tgt="Commander Ashlam Valorfist"}, [37]={npc="Nathaniel Dumah", tgt="Nathaniel Dumah"}, [38]={npc="Nathaniel Dumah", tgt="Nathaniel Dumah"}, [39]={npc="Termite Barrel", npcObj=true}, [40]={npc="Termite Barrel", npcObj=true}, [41]={hint="Release the Plagueland Termites in the Northridge Lumber Mill, then return with the Barrel of Plagueland Termites to Nathaniel Dumah at Chillwind Camp in Western Plaguelands."}, [42]={npc="Kirsta Deepshadow", tgt="Kirsta Deepshadow"}, [43]={hint="Kill 2 Scarlet Medics, 2 Scarlet Hunters, 2 Scarlet Magi and 2 Scarlet Knights before returning to Kirsta Deepshadow in Western Plaguelands."}, [44]={npc="Kirsta Deepshadow", tgt="Kirsta Deepshadow"}, [45]={npc="Kirsta Deepshadow", tgt="Kirsta Deepshadow"}, [46]={hint="Kill Huntsman Radley and Cavalier Durgen before returning to Kirsta Deepshadow in Western Plaguelands."}, [47]={npc="Kirsta Deepshadow", tgt="Kirsta Deepshadow"}, [48]={npc="Kirsta Deepshadow", tgt="Kirsta Deepshadow"}, [49]={hint="Enter Hearthglen and find a high vantage point from which you can see the town and gauge the Scarlet Crusade's forces, then return to Kirsta Deepshadow in Western Plaguelands.", tag="Unverified", desc="The coordinates are approximate. There are Scarlet Crusade guards at the entrance and by the tower; pull them one at a time."}, [50]={npc="Kirsta Deepshadow", tgt="Kirsta Deepshadow"}, [51]={npc="Nathaniel Dumah", tgt="Nathaniel Dumah"}, [52]={desc="There's no flight point nearby: walk back south to Chillwind Camp and fly from there, or head east across the Thondroril River and ride through the Eastern Plaguelands to the chapel."}, [53]={npc="Carlin Redpath", tgt="Carlin Redpath", tag="Optional"}, [54]={npc="Carlin Redpath", tgt="Carlin Redpath"}, [56]={npc="Royal Historian Archesonus", tgt="Royal Historian Archesonus"}, [58]={npc="Royal Factor Bathrilor", tgt="Royal Factor Bathrilor"}, [59]={npc="Royal Factor Bathrilor", tgt="Royal Factor Bathrilor"}, [60]={npc="Ol' Emma", tgt="Ol' Emma"}, [61]={tag="Optional", desc="Only go to Lakeshire if you have The True Master (The True Masters); otherwise skip steps 61-63 and fly straight from Stormwind to Morgan's Vigil."}, [62]={npc="Magistrate Solomon", tgt="Magistrate Solomon", tag="Optional"}, [63]={npc="Magistrate Solomon", tgt="Magistrate Solomon", tag="Optional"}, [65]={npc="Marshal Maxwell", tgt="Marshal Maxwell", tag="Optional"}, [66]={npc="Marshal Maxwell", tgt="Marshal Maxwell", tag="Optional"}, [67]={hint="Speak with Ragged John to learn of Marshal Windsor's fate and return to Marshal Maxwell when you have completed this task."}, [68]={npc="Oralius", tgt="Oralius", tag="Optional"}, [69]={hint="Take Gor'tesh's Lopped Off Head and place it at the top of Dreadmaul Rock. Look for a soft dirt mound to plant the pike.", tag="Optional", desc="This is a dedicated detour with no other objectives nearby. Skip it if you're in a hurry."}, [70]={npc="Marshal Maxwell", tgt="Marshal Maxwell", tag="Optional"}, [71]={npc="Oralius", tgt="Oralius", tag="Optional"}, [72]={text="Not 60 yet? Run Blackrock Depths once. If that's still not enough, farm Stratholme or Scholomance."}}},
    ["05-d13"] = {name="Stratholme", entrance="Eastern Plaguelands 26.52, 10.36", steps={[2]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon prereq"}, [3]={hint="Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete.", tag="Dungeon prereq"}, [4]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon prereq"}, [5]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon prereq"}, [6]={hint="Slay 30 Plaguebats and return to Tirion Fordring.", tag="Dungeon prereq"}, [7]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon prereq"}, [8]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon prereq"}, [9]={hint="Seek out the Carrion Grubs and Devourers of the region. Slay them and harvest their meat. Return to Tirion Fordring when you have gathered 15 Slabs of Carrion Worm Meat.", tag="Dungeon prereq"}, [10]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon prereq"}, [11]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon prereq"}, [12]={hint="Listen to what Tirion Fordring has to say.", tag="Dungeon prereq"}, [13]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon prereq"}, [14]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon prereq"}, [15]={hint="Travel to the Undercroft - at the southernmost section of the Eastern Plaguelands - and recover Taelan's Hammer. Return to Tirion Fordring upon completion of your objective.", tag="Dungeon prereq"}, [16]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon prereq"}, [17]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon prereq"}, [18]={hint="Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective.", tag="Dungeon prereq"}, [19]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon prereq"}, [20]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon prereq"}, [21]={npc="Artist Renfray", tgt="Artist Renfray", tag="Dungeon prereq"}, [22]={npc="Artist Renfray", tgt="Artist Renfray"}, [23]={text="From Chillwind Camp, go east through Western Plaguelands into Eastern Plaguelands, then follow the road north to Stratholme.", tag="Unverified"}, [24]={text="Stratholme entrance"}, [25]={text="Leave Stratholme and go southeast to Light's Hope Chapel.", tag="Unverified"}}},
    ["05-d12"] = {name="Blackrock Depths", entrance="Searing Gorge 34.80, 85.30", pickup="Pick up Kharan Mighthammer once you've turned in The Smoldering Ruins of Thaurissan at Ironforge. The Burning Steppes quests are accepted around Morgan's Vigil.", pickupS={{"Pick up Kharan Mighthammer once you've turned in The Smoldering Ruins of Thaurissan at Ironforge"}, {"The Burning Steppes quests are accepted around Morgan's Vigil"}}, steps={[1]={npc="Royal Historian Archesonus", tgt="Royal Historian Archesonus", tag="Dungeon prereq"}, [2]={hint="Listen to Royal Historian Archesonus recant the history of Thaurissan.", tag="Dungeon prereq"}, [3]={npc="Royal Historian Archesonus", tgt="Royal Historian Archesonus", tag="Dungeon prereq"}, [4]={npc="Royal Historian Archesonus", tgt="Royal Historian Archesonus", tag="Dungeon prereq"}, [5]={hint="Venture to the Ruins of Thaurissan in the Burning Steppes and recover information from the Thaurissan Relics. Return to Royal Historian Archesonus when you have recovered the information.", tag="Dungeon prereq"}, [6]={npc="Royal Historian Archesonus", tgt="Royal Historian Archesonus", tag="Dungeon prereq"}, [7]={npc="King Magni Bronzebeard", tgt="King Magni Bronzebeard", desc="The prerequisite is Ruins of Thaurissan (The Smoldering Ruins of Thaurissan); pick it up after turning in at Ironforge at stop 59 of chapter 04."}, [8]={npc="Ragnar Thunderbrew", tgt="Ragnar Thunderbrew", tag="Optional", desc="Turn it in only once you've picked it up in the Blasted Lands."}, [9]={npc="Ragnar Thunderbrew", tgt="Ragnar Thunderbrew", tag="Optional", desc="Kharanos is out of the way; skip it unless you want to make the detour."}, [10]={npc="Oralius", tgt="Oralius"}, [11]={npc="Maxwort Uberglint", tgt="Maxwort Uberglint"}, [12]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon prereq"}, [13]={hint="Listen as Kalaran Windblade tells his story.", tag="Dungeon prereq"}, [14]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon prer