    [4961] = {n="Cleansing of the Orb of Orahil", d="Kill the Demon of the Orb, then speak with Tabetha.", tgo={{"Demon of the Orb"}}},
    [4962] = {n="Shard of a Felhound", d="Take the Felhas Ruby and use it on one of the Felhounds found in Desolace. After successful, bring the Felhas Ruby and the Imprisoned Felhound Spirit back to Menara Voidrender in the Barrens.", tgo={{"Mana Eater"}}},
    [4963] = {n="Shard of an Infernal", d="Take the Infus Emerald and use it on one of the Infernals found in Desolace. After successful, bring the Infus Emerald and the Imprisoned Infernal Spirit back to Menara Voidrender in the Barrens.", tgo={{"Lesser Infernal"}}},
    [4964] = {n="The Completed Orb of Dar'Orahil", d="Wait for Menara Voidrender to complete the Orb of Dar'Orahil and then speak to her again.", tgo={{"Menara Voidrender"}}},
    [4971] = {n="A Matter of Time", d="Use the Temporal Displacer near one of Andorhal's silos and uncover Temporal Parasites.\nSlay 10 Temporal Parasites, and then return the Temporal Displacer to Chromie in the Andorhal Inn, Western Plaguelands.", tgo={{"Temporal Parasite"}}},
    [4975] = {n="The Completed Orb of Noh'Orahil", d="Wait for Menara Voidrender to complete the Orb of Noh'Orahil and then speak to her again.", tgo={{"Menara Voidrender"}}},
    [4976] = {n="Returning the Cleansed Orb", d="Return the Cleansed Infernal Orb to Menara Voidrender in the Barrens."},
    [4984] = {n="The Wildlife Suffers Too", d="Destroy 8 Diseased Wolves, and then return to Mulgris Deepriver at the Writhing Haunt, Western Plaguelands.", tgo={{"Diseased Wolf"}}},
    [4985] = {n="The Wildlife Suffers Too", d="Destroy 8 Diseased Grizzlies, and then return to Mulgris Deepriver at the Writhing Haunt, Western Plaguelands.", tgo={{"Diseased Grizzly"}}},
    [4986] = {n="Glyphed Oaken Branch", d="Based on the magic enchanted within the Glyphed Oaken Branch, its delivery to the Cenarion Circle in Darnassus is the next step the tauren druid sought. Seek one of the druids there for assistance."},
    [5021] = {n="Better Late Than Never", d="The ramblings of the ghostly woman indicated that she needed a package delivered. She claimed that it was where her horse was. As to where the horse is or where the package was to be delivered - the ghost remains incomprehensible."},
    [5022] = {n="Better Late Than Never", d="Check with the Royal Factors of Stormwind to learn the whereabouts of an Emma Felstone. There is usually a census officer located in City Hall."},
    [5048] = {n="Good Natured Emma", d="Find Ol' Emma in Stormwind and see if she is in fact Emma Felstone. If she is, then perhaps she'd like the package Janice Felstone made for her."},
    [5061] = {n="Aquatic Form", d="Return to Darnassus and show Mathrengyl Bearwalker the Pendant of the Sea Lion."},
    [5066] = {n="A Call to Arms: The Plaguelands!", d="Seek out Commander Ashlam Valorfist. His base camp is located at Chillwind Camp, north of the Alterac Mountains."},
    [5082] = {n="Threat of the Winterfall", d="Donova Snowden in Winterspring wants you to kill 8 Winterfall Pathfinders, 8 Winterfall Den Watchers, and 8 Winterfall Totemics.", tgo={{"Winterfall Pathfinder"}, {"Winterfall Den Watcher"}, {"Winterfall Totemic"}}},
    [5083] = {n="Winterfall Firewater", d="Bring the Empty Firewater Flask to Donova Snowden in Winterspring."},
    [5084] = {n="Falling to Corruption", d="Search the Deadwood furbolg camp in northern Felwood for a clue."},
    [5085] = {n="Mystery Goo", d="Report back to Donova Snowden with your findings."},
    [5092] = {n="Clear the Way", d="Kill 10 Skeletal Flayers and 10 Slavering Ghouls in Sorrow Hill.\nReturn to Commander Ashlam Valorfist at Chillwind Camp, Western Plaguelands.", tgo={{"Skeletal Flayer"}, {"Slavering Ghoul"}}},
    [5097] = {n="All Along the Watchtowers", d="Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it.\nOnce all four towers are marked, return the Beacon Torch to Commander Ashlam Valorfist in Chillwind Camp, Western Plaguelands.", tgo={{"Andorhal Tower One"}, {"Andorhal Tower Two"}, {"Andorhal Tower Three"}, {"Andorhal Tower Four"}}},
    [5149] = {n="Pamela's Doll", d="Find Pamela's doll."},
    [5152] = {n="Auntie Marlene", d="Speak with Marlene, south of the Ruins of Andorhal."},
    [5153] = {n="A Strange Historian", d="Bring Joseph's Wedding Ring to Chromie.", objs={"Joseph Redpath's Monument"}},
    [5154] = {n="The Annals of Darrowshire", d="Bring the Annals of Darrowshire to Chromie in Andorhal.", objs={"Musty Tome"}},
    [5155] = {n="Forces of Jaedenar", d="Enter Jaedenar and slay 4 Jaedenar Hounds, 4 Jaedenar Guardsmen, 6 Jaedenar Adepts, and 6 Jaedenar Cultists before returning to Greta Mosshoof in Felwood.", tgo={{"Jaedenar Hound"}, {"Jaedenar Guardian"}, {"Jaedenar Adept"}, {"Jaedenar Cultist"}}},
    [5156] = {n="Verifying the Corruption", d="Seek out and destroy 2 Entropic Beasts and 2 Entropic Horrors while exploring Shatter Scar Vale. After checking to see if the craters there are still filled with corrupt fel water, return to Taronn Redfeather in Felwood.", tgo={{"Entropic Beast"}, {"Entropic Horror"}}},
    [5157] = {n="Collection of the Corrupt Water", d="Take the Empty Canteen to the Moon Well in the center of Jaedenar and fill it before returning to Greta Mosshoof in Felwood.", objs={"Corrupt Jaedenar Moonwell"}},
    [5158] = {n="Seeking Spiritual Aid", d="Take the Corrupt Moon Well Water to Islen Waterseer in the Barrens."},
    [5159] = {n="Cleansed Water Returns to Felwood", d="Take the Purified Moon Well Water to Greta Mosshoof in Felwood."},
    [5168] = {n="Heroes of Darrowshire", d="Bring Davil's Libram and Redpath's Shield to Carlin Redpath.", objs={"Davil's Libram", "Redpath's Shield"}},
    [5181] = {n="Villains of Darrowshire", d="Bring the Skull of Horgus and the Shattered Sword of Marduk to Carlin Redpath at Light's Hope Chapel.", objs={"Horgus' Skull", "Shattered Sword of Marduk"}},
    [5210] = {n="Brother Carlin", d="Bring the Extended Annals of Darrowshire to Carlin Redpath in Eastern Plaguelands."},
    [5211] = {n="Defenders of Darrowshire", d="Free 15 Darrowshire Spirits and return to Carlin Redpath.", tgo={{"Darrowshire Spirit"}}},
    [5215] = {n="The Scourge Cauldrons", d="Speak with High Priestess MacDonnell at Chillwind Point, Western Plaguelands."},
    [5216] = {n="Target: Felstone Field", d="Go to Felstone Field in Western Plaguelands to locate and defeat the Cauldron Lord present there. It may have a key that will allow access to the cauldron. You must have the Empty Felstone Field Bottle with you to secure a sample of the poisons used inside the cauldron.", tgo={{"Cauldron Lord Bilemaw"}}},
    [5217] = {n="Return to Chillwind Camp", d="Bring the Filled Felstone Field Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands."},
    [5219] = {n="Target: Dalson's Tears", d="Go to Dalson's Tears in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Dalson's Tears Bottle with you to secure a sample of the poisons used inside the cauldron.", tgo={{"Cauldron Lord Malvinious"}}},
    [5220] = {n="Return to Chillwind Camp", d="Bring the Filled Dalson's Tears Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands."},
    [5222] = {n="Target: Writhing Haunt", d="Go to the Writhing Haunt in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Writhing Haunt Bottle with you to secure a sample of the poisons used inside the cauldron.", tgo={{"Cauldron Lord Razarch"}}},
    [5223] = {n="Return to Chillwind Camp", d="Bring the Filled Writhing Haunt Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands."},
    [5225] = {n="Target: Gahrron's Withering", d="Go to Gahrron's Withering in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Gahrron's Withering Bottle with you to secure a sample of the poisons used inside the cauldron.", tgo={{"Cauldron Lord Soulwrath"}}},
    [5226] = {n="Return to Chillwind Camp", d="Bring the Filled Gahrron's Withering Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands."},
    [5237] = {n="Mission Accomplished!"},
    [5241] = {n="Uncle Carlin", d="Find Carlin Redpath."},
    [5244] = {n="The Ruins of Kel'Theril", d="Speak with Jaron Stoneshaper in Starfall Village."},
    [5245] = {n="Troubled Spirits of Kel'Theril", d="Use Jaron's Pick to find the four Highborne Relic Fragments. Bring them to Aurora Skycaller in Eastern Plaguelands.", objs={"Highborne Relic Fragment"}},
    [5250] = {n="Starfall", d="Find Starfall in Winterspring and speak with Wynd Nightchaser."},
    [5261] = {n="Eagan Peltskinner", d="Speak with Eagan Peltskinner."},
    [5401] = {n="Argent Dawn Commission"},
    [5541] = {n="Ammo for Rumbleshot", d="Bring Rumbleshot's Ammo to Hegnar Rumbleshot in Dun Morogh.", objs={"Ammo Crate"}},
    [5542] = {n="Demon Dogs", d="Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete.", tgo={{"Plaguehound Runt"}, {"Plaguehound"}, {"Frenzied Plaguehound"}}},
    [5543] = {n="Blood Tinged Skies", d="Slay 30 Plaguebats and return to Tirion Fordring.", tgo={{"Plaguebat"}}},
    [5544] = {n="Carrion Grubbage", d="Seek out the Carrion Grubs and Devourers of the region. Slay them and harvest their meat. Return to Tirion Fordring when you have gathered 15 Slabs of Carrion Worm Meat.", tgo={{"Carrion Grub", "Carrion Devourer"}}},
    [5545] = {n="A Bundle of Trouble", d="Bring 8 Bundles of Wood to Raelen at the Eastvale Logging Camp.", objs={"Bundle of Wood"}},
    [5601] = {n="Sister Pamela", d="Find Pamela Redpath in Darrowshire."},
    [5621] = {n="Garments of the Moon", d="Find Sentinel Shaya and heal her wounds using Lesser Heal (Rank 2). Afterwards, grant her Power Word: Fortitude and then return to Laurna Morninglight in Dolanaar.", tgo={{"Sentinel Shaya"}}},
    [5622] = {n="In Favor of Elune", d="Speak to Laurna Morninglight in Teldrassil."},
    [5623] = {n="In Favor of the Light", d="Speak to Priestess Josetta in Elwynn Forest."},
    [5624] = {n="Garments of the Light", d="Find Guard Roberts and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Priestess Josetta in Goldshire.", tgo={{"Guard Roberts"}}},
    [5625] = {n="Garments of the Light", d="Find Mountaineer Dolf and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Maxan Anvol in Kharanos.", tgo={{"Mountaineer Dolf"}}},
    [5626] = {n="In Favor of the Light", d="Speak to Maxan Anvol in Dun Morogh."},
    [5627] = {n="Stars of Elune"},
    [5629] = {n="Returning Home", d="Speak to Priestess Alathea in Darnassus."},
    [5634] = {n="Desperate Prayer"},
    [5645] = {n="A Lack of Fear", d="Speak to High Priest Rohan in Ironforge."},
    [5672] = {n="Elune's Grace"},
    [5676] = {n="Arcane Feedback"},
    [5713] = {n="One Shot. One Kill.", d="Protect Sentinel Aynasha, then speak with Onaeya at Maestra's Post in Ashenvale."},
    [5742] = {n="Redemption", d="Listen to what Tirion Fordring has to say.", tgo={{"Tirion Fordring"}}},
    [5762] = {n="Hemet Nesingwary", d="Take Kravel's Crate to Hemet Nesingwary in Stranglethorn."},
    [5781] = {n="Of Forgotten Memories", d="Travel to the Undercroft - at the southernmost section of the Eastern Plaguelands - and recover Taelan's Hammer. Return to Tirion Fordring upon completion of your objective.", tgo={{"Mercutio Filthgorger"}}},
    [5845] = {n="Of Lost Honor", d="Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective.", objs={"Symbol of Lost Honor"}},
    [5846] = {n="Of Love and Family", d="Travel to island of Caer Darrow, in the south-central region of the Plaguelands, and look for any clues as to the whereabouts of the painting."},
    [5848] = {n="Of Love and Family", d="Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world.\nReturn the painting to Tirion Fordring.", objs={"Unfinished Painting"}},
    [5863] = {n="The Dunemaul Compound", d="Andi Lynn in Gadgetzan wants you to destroy the Dunemaul Compound by killing 10 Dunemaul Brutes, 10 Dunemaul Enforcers, and Gor'marok the Ravager.", tgo={{"Dunemaul Brute"}, {"Dunemaul Enforcer"}, {"Gor'marok the Ravager"}}},
    [5903] = {n="A Plague Upon Thee", d="Use the Empty Termite Jar on the Termite Mounds in Eastern Plaguelands. After you've gathered 100 Plagueland Termites, return to Nathaniel Dumah at Chillwind Camp in Western Plaguelands.", objs={"Large Termite Mound"}},
    [5904] = {n="A Plague Upon Thee", d="Find someplace suitable in the center of the Northridge Lumber Mill in Western Plaguelands to place the Barrel of Plagueland Termites."},
    [5921] = {n="Moonglade", d="Use the spell \"Teleport: Moonglade\" to travel to Moonglade. When you arrive, speak with Dendrite Starblaze in the village of Nighthaven."},
    [5929] = {n="Great Bear Spirit", d="Seek out the Great Bear Spirit in northwestern Moonglade and learn what it has to share with you about the nature of the bear. When finished, return to Dendrite Starblaze in Nighthaven, Moonglade.", tgo={{"Great Bear Spirit"}}},
    [5931] = {n="Back to Darnassus", d="Return to Darnassus and speak with Mathrengyl Bearwalker in the Cenarion Enclave."},
    [6001] = {n="Body and Heart", d="Use the Cenarion Moondust on the Moonkin Stone of Auberdine to bring forth Lunaclaw. From there, you must face Lunaclaw and earn the strength of body and heart it possesses.\nSpeak with Mathrengyl Bearwalker in Darnassus when you are done.", tgo={{"Lunaclaw Spirit"}}},
    [6004] = {n="Unfinished Business", d="Kill 2 Scarlet Medics, 2 Scarlet Hunters, 2 Scarlet Magi and 2 Scarlet Knights before returning to Kirsta Deepshadow in Western Plaguelands.", tgo={{"Scarlet Medic"}, {"Scarlet Hunter"}, {"Scarlet Mage"}, {"Scarlet Knight"}}},
    [6021] = {n="Zaeldarr the Outcast", d="Bring Zaeldarr's Head to Caretaker Alen at Light's Hope Chapel.", tgo={{"Zaeldarr the Outcast"}}},
    [6023] = {n="Unfinished Business", d="Kill Huntsman Radley and Cavalier Durgen before returning to Kirsta Deepshadow in Western Plaguelands.", tgo={{"Huntsman Radley"}, {"Cavalier Durgen"}}},
    [6024] = {n="Hameya's Plea", d="Kill Infiltrator Hameya. Use his key on the Mound of Dirt behind the Undercroft.", tgo={{"Infiltrator Hameya"}}},
    [6025] = {n="Unfinished Business", d="Enter Hearthglen and find a high vantage point from which you can see the town and gauge the Scarlet Crusade's forces, then return to Kirsta Deepshadow in Western Plaguelands."},
    [6028] = {n="The Everlook Report", d="Deliver the Everlook Report to Argent Officer Pureheart at Chillwind Camp, Western Plaguelands."},
    [6030] = {n="Duke Nicholas Zverenhoff", d="Deliver the book, \"Studies in Spirit Speaking\", to Duke Nicholas Zverenhoff at Light's Hope Chapel, Eastern Plaguelands."},
    [6063] = {n="Taming the Beast", d="Use the Taming Rod to tame a Webwood Lurker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar.", tgo={{"Webwood Lurker"}}},
    [6064] = {n="Taming the Beast", d="Use the Taming Rod to tame a Large Crag Boar. Practice your skills, then return the Taming Rod to Grif Wildheart in Kharanos.", tgo={{"Large Crag Boar"}}},
    [6084] = {n="Taming the Beast", d="Use the Taming Rod to tame a Snow Leopard. Practice your skills, then return to Grif Wildheart in Kharanos.", tgo={{"Snow Leopard"}}},
    [6085] = {n="Taming the Beast", d="Use the Taming Rod to tame an Ice Claw Bear. Practice your skills, then return the Taming Rod to Grif Wildheart in Kharanos.", tgo={{"Ice Claw Bear"}}},
    [6086] = {n="Training the Beast", d="Speak with Belia Thundergranite in Ironforge."},
    [6101] = {n="Taming the Beast", d="Use the Taming Rod to tame a Nightsaber Stalker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar.", tgo={{"Nightsaber Stalker"}}},
    [6102] = {n="Taming the Beast", d="Use the Taming Rod to tame a Strigid Screecher. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar.", tgo={{"Strigid Screecher"}}},
    [6103] = {n="Training the Beast", d="Speak to Jocaste in the Cenarion Enclave, in Darnassus."},
    [6121] = {n="Lessons Anew", d="Travel to Moonglade and speak with Dendrite Starblaze in the village of Nighthaven."},
    [6122] = {n="The Principal Source", d="Use the Empty Cliffspring Falls Sampler to draw a sample of water from the mouth of the cave by the falls.\nDeliver the Filled Cliffspring Falls Sampler to Alanndarian Nightsong in Auberdine, Darkshore.", objs={"Cliffspring Falls Cave Mouth"}},
    [6123] = {n="Gathering the Cure", d="Bring 5 Earthroot and 12 Lunar Funguses to Alanndarian Nightsong in Auberdine so she may make a curative salve.", tgo={{"Lasher Sproutling", "Wrathvine"}, {}}, objs={"Lunar Fungal Bloom"}},
    [6124] = {n="Curing the Sick", d="Use the Curative Animal Salve on 10 Sickly Deer that are located throughout Darkshore; doing so should cure them. Sickly Deer have been reported starting south of the Cliffspring River to the north of Auberdine and extending all the way into southern Darkshore where the edge of Ashenvale begins.", tgo={{"Sickly Deer"}}},
    [6125] = {n="Power over Poison", d="Return to Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus."},
    [6134] = {n="Ghost-o-plasm Round Up", d="Bring 8 Ghost-o-plasms and the Crate of Ghost Magnets to Hornizz Brimbuzzle in Desolace.", tgo={{"Magrami Spectre"}}},
    [6182] = {n="The First and the Last", d="Speak with Mathias Shaw in Old Town Stormwind. He resides in the Barracks."},
    [6183] = {n="Honor the Dead", d="Speak with Mathias Shaw again if you wish to accept his task."},
    [6184] = {n="Flint Shadowmore", d="Travel to Chillwind Camp in the Western Plaguelands and meet up with your contact, Flint Shadowmore."},
    [6185] = {n="The Eastern Plagues", d="Scour the Eastern Plaguelands for clues as to the \"Blightcaller\" and the missing SI:7 agents. If you find any SI:7 Insignias, return them to Flint Shadowmore at Chillwind Camp.", objs={"Mangled Human Remains"}},
    [6341] = {n="The Bounty of Teldrassil", d="Bring Nessa's Collection to Vesprystus."},
    [6342] = {n="Flight to Auberdine", d="Ride a hippogryph to Auberdine from the hippogryph master Vesprystus, then bring Nessa's Collection to Laird."},
    [6343] = {n="Return to Nessa", d="Bring Laird's Response to Nessa Shadowsong."},
    [6344] = {n="Nessa Shadowsong", d="Speak with Nessa Shadowsong."},
    [6387] = {n="Honor Students", d="Bring Brock's List to Thorgrum Borrelson in Thelsamar."},
    [6388] = {n="Gryth Thurden", d="Bring the Honorary Picks to Gryth Thurden in Ironforge."},
    [6389] = {n="A Plague Upon Thee", d="Release the Plagueland Termites in the Northridge Lumber Mill, then return with the Barrel of Plagueland Termites to Nathaniel Dumah at Chillwind Camp in Western Plaguelands."},
    [6391] = {n="Ride to Ironforge", d="Buy a gryphon to Ironforge from the gryphon master Thorgrum Borrelson, then bring Brock's List to Golnir Bouldertoe in Ironforge."},
    [6392] = {n="Return to Brock", d="Buy a gryphon to Thelsamar from the gryphon master Gryth Thurden, then bring the Honorary Picks to Brock Stoneseeker in Thelsamar."},
    [6603] = {n="Trouble in Winterspring!", d="Find Donova Snowden near the hot springs in Winterspring."},
    [6604] = {n="Enraged Wildkin", d="Speak with Jaron Stoneshaper at Starfall Village."},
    [6681] = {n="The Manor, Ravenholdt", d="Take the Seal of Ravenholdt to Fahrad at Ravenholdt Manor, hidden away in the hills of Hillsbrad.\nYour cunning will be tested along the way. Be prepared.", tgo={{"Ravenholdt"}}},
    [6701] = {n="Syndicate Emblems", d="Loot from: Syndicate Assassin, Syndicate Conjuror, Syndicate Footpad", tgo={{"Syndicate Assassin", "Syndicate Conjuror", "Syndicate Footpad", "Syndicate Highwayman", "Syndicate Mercenary", "Syndicate Pathstalker", "Syndicate Prowler", "Syndicate Spy"}}},
    [7383] = {n="Crown of the Earth", d="Fill the Amethyst Phial and bring it back to Corithras Moonrage in Dolanaar.", objs={"Oracle Glade Moonwell"}},
    [7601] = {n="What Niby Commands", d="Speak with Impsy in Felwood."},
    [7602] = {n="Flawless Fel Essence", d="Impsy in Felwood has asked that you bring him three Flawless Fel Essences originating from three distinct locations.\nThe Legashi Satyrs of Azshara hold the Flawless Fel Essence of their region. The Jaedenar Legionnaires of Jaedenar hold the Flawless Fel Essence of their region. The Felguard Sentries of the Blasted Lands hold the Flawless Fel Essence of their region.\nRecover the Flawless Fel Essences and return to Impsy in Felwood.", tgo={{"Legashi Satyr", "Legashi Rogue", "Legashi Hellcaller", "Legashi Soulstealer", "Legashi Hellraiser", "Legashi Blackguard"}, {"Jaedenar Legionnaire"}, {"Felguard Sentry"}}},
    [7603] = {n="Kroshius' Infernal Core", d="Search Shatter Scar Vale in Felwood for the remains of Kroshius. When you locate the remains, use the Fel Fire near them and await Kroshius' return. When the infernal has awoken, slay him and take from his corpse Kroshius' Infernal Core.\nReturn Kroshius' Infernal Core to Niby the Almighty in Felwood.", tgo={{"Kroshius"}, {"Kroshius"}}},
    [7701] = {n="WANTED: Overseer Maltorius", d="Deep within the Slag Pit of the Cauldron, in the Searing Gorge, you will find the traitorous Dark Iron dwarf named Overseer Maltorius.\nSlay Overseer Maltorius and take his head. Return the head to Lookout Captain Lolo Longstriker in the Searing Gorge for your reward.", tgo={{"Overseer Maltorius"}}},
    [7722] = {n="What the Flux?", d="Somewhere in the Slag Pit of the Cauldron you will find the Secret Plans: Fiery Flux that Overseer Maltorius stole. Find those plans and return them to Master Smith Burninate in the Searing Gorge.", objs={"Secret Plans: Fiery Flux"}},
    [7723] = {n="Curse These Fat Fingers", d="Hansel Heavyhands wants you to kill 20 Heavy War Golems.\nThe Heavy War Golems wander the areas surrounding the Cauldron in the Searing Gorge. When you've killed enough, return to Hansel in Searing Gorge.", tgo={{"Heavy War Golem"}}},
    [7724] = {n="Fiery Menace!", d="Hansel Heavyhands wants you to kill 20 Greater Lava Spiders in the Searing Gorge. You can find Greater Lava Spiders in the plateaus and lava pools of the Searing Gorge.\nReturn to Hansel Heavyhands in the Searing Gorge when you have killed enough Greater Lava Spiders.", tgo={{"Greater Lava Spider"}}},
    [7727] = {n="Incendosaurs? Whateverosaur is More Like It", d="Hansel Heavyhands wants you to kill 20 Incendosaurs.\nYou will find Incendosaurs occupying the lava pools inside the Slag Pit. The Slag Pit can be found in the Cauldron of the Searing Gorge.\nReturn to Hansel Heavyhands in the Searing Gorge when you have killed enough Incendosaurs.", tgo={{"Incendosaur"}}},
    [7728] = {n="STOLEN: Smithing Tuyere and Lookout's Spyglass", d="Find and return the Smithing Tuyere and Lookout's Spyglass to Taskmaster Scrange in the Searing Gorge.\nThe only information you have about these items is the following: They were definitely stolen by Dark Iron dwarves. The Smithing Tuyere is a blacksmithing tool used by blacksmiths and the Lookout's Spyglass is an invaluable monitoring tool to lookouts.", tgo={{"Dark Iron Steamsmith"}, {"Dark Iron Lookout"}}},
    [7729] = {n="JOB OPPORTUNITY: Culling the Competition", d="Slay 15 Dark Iron Taskmasters and 15 Dark Iron Slavers. Return to Taskmaster Scrange in the Searing Gorge once you have accomplished this task.", tgo={{"Dark Iron Taskmaster"}, {"Dark Iron Slaver"}}},
    [7733] = {n="Improved Quality", d="Bring 10 Rage Scar Yeti Hides to Pratt McGrubben at Feathermoon Stronghold, Feralas.", tgo={{"Rage Scar Yeti", "Elder Rage Scar", "Ferocious Rage Scar", "Lurking Feral Scar"}}},
    [7735] = {n="Pristine Yeti Hide", d="Bring the Pristine Yeti Hide to Pratt McGrubben at the Feathermoon Stronghold, Feralas."},
    [7791] = {n="A Donation of Wool", d="Use/collect: Alterac Granite, Tattered Chest, Battered Chest", objs={"Alterac Granite", "Tattered Chest", "Battered Chest"}},
    [7793] = {n="A Donation of Silk", d="Use/collect: Alterac Granite, Battered Chest, Solid Chest", objs={"Alterac Granite", "Battered Chest", "Solid Chest"}},
    [8151] = {n="The Hunter's Charm", d="Speak to Ogtinc in Azshara."},
    [8153] = {n="Courser Antlers", d="Bring a pair of Perfect Courser Antlers to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast of the Ruins of Eldarath.", tgo={{"Mosshoof Courser"}}},
